def _ndl_render_token_line_executable_v37(tokens, vn=None, line_no=None,
                                              consts=None, method_set=None):
    """V37: Turn ONE f_lineno token group into a tentative Python statement.

    Conservative: only fires when the tokens UNAMBIGUOUSLY form one of:
      a) receiver.method(args) chain (e.g. ['self','session','get','url'])
         -> `self.session.get(url)`
      b) receiver.method() (no args, e.g. ['self','close'])
         -> `self.close()`
      c) `return <expr>` (e.g. ['return', 'True'])
         -> `return True`
      d) `if <subject> <op> <literal>:` (e.g. ['status','==','OK'])
         -> `if status == 'OK':`
      e) assignment: `<var> = <expr>` when first token is a plausible
         local varname and the rest form an expr.
    Returns the assembled statement string, or None to keep the comment.

    NEVER fabricates: unknown tokens stay as `_v`, `_attr` placeholders.
    """
    if not tokens or not isinstance(tokens, (list, tuple)):
        return None
    toks = [t for t in tokens if t]
    if not toks:
        return None

    # Pattern c: return <expr>
    if toks[0] == 'return':
        rest = toks[1:]
        if not rest:
            return 'return'
        # Single literal or identifier
        if len(rest) == 1:
            return 'return ' + _ndl_render_token_atom_v37(rest[0])
        # `return X.method(args)`
        expr = _ndl_render_token_chain_v37(rest, vn=vn, consts=consts)
        if expr:
            return 'return ' + expr
        return None

    # Pattern e (CHECK FIRST): <var> = <expr> (assignment)
    # Triggered when second token is `=`. This must be checked BEFORE
    # pattern a/b so `r = self.session.get(url)` doesn't get mis-parsed
    # as a chain starting with `r`.
    if len(toks) >= 3 and toks[1] == '=':
        first = toks[0]
        if re.fullmatch(r'[a-z_][a-zA-Z0-9_]*', first):
            # Skip the `=` token, render the rest as a chain
            expr = _ndl_render_token_chain_v37(toks[2:], vn=vn, consts=consts)
            if expr:
                return f'{first} = {expr}'

    # Pattern d: if <subject> <op> <literal>
    # Tokens like: ['status', '==', "'OK'"] or ['x', 'in', 'seq']
    _CMP_OPS = {'==', '!=', '<', '>', '<=', '>=', 'in', 'not', 'is', 'and', 'or'}
    if len(toks) >= 3 and any(t in _CMP_OPS for t in toks[1:-1]):
        # Find the comparison op
        for i, t in enumerate(toks[1:-1], 1):
            if t in ('==', '!=', '<', '>', '<=', '>='):
                lhs = _ndl_render_token_chain_v37(toks[:i], vn=vn, consts=consts)
                rhs = _ndl_render_token_atom_v37(toks[i+1])
                if lhs and rhs:
                    return f'if {lhs} {t} {rhs}:'
            elif t == 'in':
                lhs = _ndl_render_token_chain_v37(toks[:i], vn=vn, consts=consts)
                rhs = _ndl_render_token_chain_v37(toks[i+1:], vn=vn, consts=consts)
                if lhs and rhs:
                    return f'if {lhs} in {rhs}:'
            elif t == 'is' and i + 1 < len(toks):
                lhs = _ndl_render_token_chain_v37(toks[:i], vn=vn, consts=consts)
                rhs = _ndl_render_token_atom_v37(toks[i+1])
                if lhs and rhs:
                    return f'if {lhs} is {rhs}:'
            elif t == 'not' and i + 1 < len(toks) and toks[i+1] == 'in':
                if i + 2 == len(toks):
                    lhs = _ndl_render_token_chain_v37(toks[:i], vn=vn, consts=consts)
                    rhs = _ndl_render_token_atom_v37(toks[i+2]) if i + 2 < len(toks) else None
                    if lhs and rhs:
                        return f'if {lhs} not in {rhs}:'

    # Pattern a/b: receiver.method(args) or receiver.attr.method(args)
    # Detect: first token is `self`/`cls`/module-name/varname, then 1+ attr
    # tokens, then optional args.
    if len(toks) >= 2 and (toks[0] in ('self', 'cls') or (
            vn and toks[0] in (set(vn) | {'requests', 'time', 'json', 're', 'os', 'sys',
                                          'random', 'BeautifulSoup', 'QThreadPool',
                                          'QTimer', 'QtWidgets', 'QtCore', 'QtGui'}))):
        chain = _ndl_render_token_chain_v37(toks, vn=vn, consts=consts)
        if chain:
            # If the chain ends with a method call, it's a statement.
            if chain.endswith(')'):
                return chain
            # Special case: 2-token chain `self.method` -> `self.method()`
            # (a bare method call with no args, common for void methods).
            if len(toks) == 2 and re.fullmatch(r'[A-Za-z_]\w*', toks[1]):
                return chain + '()'
            # Could be `self.attr = value` — handled by pattern e above.

    # V40 Pattern (f): Infer `self.` receiver from the class method set
    # OR from the known Qt/widget method set. When the first token is a
    # method name in either set, emit `self.<method>()` or
    # `self.<method>(args)`. This closes the gap for token groups like
    # ['content_layout'], ['addWidget'], ['setStyleSheet'] that have no
    # explicit receiver.
    _v40_infer_set = (method_set or set()) | _V40_QT_METHODS
    _has_self_receiver = bool(vn and ('self' in vn or 'cls' in vn))
    if toks[0] in _v40_infer_set and toks[0] not in ('self', 'cls'):
        method_name = toks[0]
        args = toks[1:]
        _prefix = 'self.' if _has_self_receiver else ''
        if not args:
            return f'{_prefix}{method_name}()'
        # Render args as atoms
        arg_strs = []
        for a in args:
            atom = _ndl_render_token_atom_v37(a)
            if atom:
                arg_strs.append(atom)
            else:
                arg_strs = None
                break
        if arg_strs is not None:
            return f'{_prefix}{method_name}({", ".join(arg_strs)})'

    # V40 Pattern (g): Single identifier that's a known method or function.
    # When the token group is just one identifier and it's in the method set
    # or QT_METHODS, emit `self.<method>()`.
    if len(toks) == 1 and toks[0] in _v40_infer_set:
        _prefix = 'self.' if _has_self_receiver else ''
        return f'{_prefix}{toks[0]}()'

    # V40 Pattern (h): Assignment to self.attr when the RHS is a method call.
    # Tokens like: ['self', 'widget', '=', 'create_button'] where
    # 'create_button' is in the method set.
    # Already handled by pattern (e) + chain renderer, but add a fallback:
    # if pattern (e) failed and we have `self.X = <method_name>`, emit it.
    if (method_set and len(toks) >= 3 and toks[1] == '='
            and toks[0] in ('self', 'cls')):
        # self.X = method_name(...)
        rhs_toks = toks[2:]
        if len(rhs_toks) == 1 and rhs_toks[0] in method_set:
            attr = toks[0] + '.' + _ndl_render_token_atom_v37(toks[0+1]) if len(toks) > 0 else None
            # Actually: self.X = method_name -> self.X = self.method_name()
            # But this is risky — skip for now.
            pass

    return None


def _ndl_render_token_atom_v37(tok):
    """Render a single token as a Python atom (literal or identifier)."""
    if not tok:
        return None
    # Already a quoted string literal
    if len(tok) >= 2 and tok[0] in ("'", '"') and tok[-1] == tok[0]:
        return tok
    # Numeric
    if re.fullmatch(r'-?\d+(?:\.\d+)?', tok):
        return tok
    # Special constants
    if tok in ('None', 'True', 'False'):
        return tok
    # Identifier
    if re.fullmatch(r'[A-Za-z_]\w*', tok):
        return tok
    # V39.4: Tuple/list/dict literal tokens like "('Ayarlar',)" or "[1, 2]"
    if tok.startswith('(') and tok.endswith(')'):
        return tok
    if tok.startswith('[') and tok.endswith(']'):
        return tok
    if tok.startswith('{') and tok.endswith('}'):
        return tok
    # Fallback: quote it as a string
    if len(tok) <= 60 and '\n' not in tok:
        return repr(tok)
    return None


def _ndl_render_token_chain_v37(toks, vn=None, consts=None):
    """Render a chain of tokens as a Python expression.

    Strategy:
      - The first token is the ROOT (self/cls/identifier/module).
      - Walk forward: each subsequent identifier is an ATTRIBUTE access
        UNLESS it is followed by more tokens (then it's a METHOD call
        with the remaining tokens as args).
      - Quoted strings and numbers are atoms (used as args).
      - The LAST identifier in the chain that has tokens after it
        becomes a method call: `root.attr.method(arg1, arg2, ...)`.
      - If no identifier has trailing tokens, it's a plain attribute:
        `root.attr.subattr`.
    """
    if not toks:
        return None
    # Strip placeholder tokens
    toks = [t for t in toks if t and t not in ('_v', '_k', '_attr', '_cond',
                                                '_item', '_subj')]
    if not toks:
        return None

    # Single atom
    if len(toks) == 1:
        return _ndl_render_token_atom_v37(toks[0])

    # Check if the chain forms `receiver.attr.method(args)`:
    # - First token is a root identifier (self/cls/module/varname)
    # - Then 1+ attribute tokens (identifiers)
    # - Then a method token (identifier) followed by args
    # OR just `receiver.attr.attr` (no method call)
    root = _ndl_render_token_atom_v37(toks[0])
    if root is None:
        return None

    # If there's only root + 1 token, it's `root.attr`
    if len(toks) == 2:
        attr = _ndl_render_token_atom_v37(toks[1])
        if attr:
            return f'{root}.{attr}'
        return None

    # Find the method position. Prefer a candidate whose *next* token looks
    # like a real argument (literal / non-methodish name). The old "first
    # identifier with a trailing token" rule packed sibling method names as
    # args (``setWindowTitle(resize, setup_ui)``).
    def _is_methodish_name(nm):
        if not re.fullmatch(r'[A-Za-z_]\w*', nm or ''):
            return False
        if nm.startswith(('on_', 'setup_', 'show_', 'get_', 'set_',
                          'update_', 'load_', 'save_', 'handle_',
                          'open_', 'close_', 'start_', 'stop_',
                          'refresh_', 'validate_', 'append_', 'remove_',
                          'log_', 'check_', 'create_', 'delete_', 'send_',
                          'parse_', 'format_', 'build_', 'make_', 'init_',
                          'run_', 'do_', 'add_', 'clear_', 'reset_',
                          'enable_', 'disable_', 'toggle_', 'emit_')):
            return True
        # CamelCase Qt/API verbs: setSingleShot, getText, addWidget, ...
        for _pfx in ('set', 'get', 'add', 'has', 'is', 'to', 'from'):
            if (nm.startswith(_pfx) and len(nm) > len(_pfx)
                    and nm[len(_pfx)].isupper()):
                return True
        return nm in ('resize', 'close', 'accept', 'reject', 'exec',
                      'connect', 'disconnect', 'emit', 'quit',
                      'processEvents', 'singleShot', 'timeout',
                      'hide', 'show', 'raise_', 'lower')

    def _looks_like_arg_token(tok):
        if tok is None:
            return False
        atom = _ndl_render_token_atom_v37(tok)
        if atom is None:
            return False
        # Literals are always args
        if (len(tok) >= 2 and tok[0] in ("'", '"') and tok[-1] == tok[0]):
            return True
        if re.fullmatch(r'-?\d+(?:\.\d+)?', tok):
            return True
        if tok in ('True', 'False', 'None', 'self', 'cls'):
            return True
        # Methodish sibling names are NOT plausible call args
        if _is_methodish_name(tok):
            return False
        return bool(re.fullmatch(r'[A-Za-z_]\w*', tok))

    candidates = []
    for i in range(1, len(toks)):
        t = toks[i]
        if not re.fullmatch(r'[A-Za-z_]\w*', t):
            continue
        if i + 1 >= len(toks):
            continue
        nxt = toks[i + 1]
        if _ndl_render_token_atom_v37(nxt) is None:
            continue
        prev = toks[i - 1]
        if not (re.fullmatch(r'[A-Za-z_]\w*', prev)
                or prev in ('self', 'cls')):
            continue
        if len(prev) >= 2 and prev[0] in ("'", '"'):
            continue
        trailing = toks[i + 1:]
        all_idents = all(re.fullmatch(r'[A-Za-z_]\w*', x) for x in trailing)
        has_literal = any(
            (len(x) >= 2 and x[0] in ("'", '"') and x[-1] == x[0])
            or re.fullmatch(r'-?\d+(?:\.\d+)?', x)
            or x in ('True', 'False', 'None')
            for x in trailing)
        score = 0
        if _looks_like_arg_token(nxt):
            score += 20
        if has_literal:
            score += 50
        if _is_methodish_name(t) or t in _V40_QT_METHODS:
            score += 40
            if all_idents and not has_literal:
                # verb-like method + localish args (log_message(msg, type))
                meth_trail = sum(1 for x in trailing if _is_methodish_name(x))
                if meth_trail == 0:
                    score += 30
                else:
                    # fused methodish.methodish (setSingleShot.timeout) → not a call
                    score -= 90
        elif all_idents and not has_literal:
            # noun/attr path (ui.btn.clicked) — do not fold as a call
            score -= 100
        meth_trail = sum(1 for x in trailing if _is_methodish_name(x))
        if len(trailing) >= 2 and meth_trail >= 2:
            score -= 80
        candidates.append((score, i))

    method_idx = None
    if candidates:
        candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
        if candidates[0][0] > 0:
            method_idx = candidates[0][1]

    if method_idx is not None:
        # Build: root.attr1.attr2.method(args)
        attrs = [_ndl_render_token_atom_v37(t) or t
                 for t in toks[1:method_idx]
                 if t and re.fullmatch(r'[A-Za-z_]\w*', t)]
        method = toks[method_idx]
        args = toks[method_idx + 1:]
        # Render args — stop before methodish sibling pools
        arg_strs = []
        for a in args:
            if _is_methodish_name(a) and arg_strs:
                # Sibling method name after real args → drop rest
                break
            if _is_methodish_name(a) and not arg_strs:
                # Leading methodish → this fold is garbage
                arg_strs = []
                break
            atom = _ndl_render_token_atom_v37(a)
            if atom:
                arg_strs.append(atom)
            else:
                break
        # Reject docstring / sibling-method name pools flattened into one call
        _methodish = sum(1 for a in arg_strs if _is_methodish_name(a))
        if len(arg_strs) >= 2 and _methodish >= 2:
            return None
        if len(arg_strs) > 6:
            return None
        # If we rejected all args as methodish, prefer attr chain / refuse
        if not arg_strs and any(_is_methodish_name(a) for a in args):
            return None
        chain = root
        if attrs:
            chain = chain + '.' + '.'.join(attrs)
        # ATTR/CALL walker hole mirror: token maps often flatten
        # ``layout.addWidget(x)`` as ``QtWidgets, QVBoxLayout, addWidget, x``.
        # Emitting ``QtWidgets.QVBoxLayout.addWidget(x)`` is unbound-method
        # garbage. Prefer a layout/instance local from co_varnames when the
        # attr path is a bare Qt class under QtWidgets/QtGui/QtCore.
        if (attrs and root in ('QtWidgets', 'QtGui', 'QtCore', 'Qt')
                and attrs[0][:1].isupper()
                and (_is_methodish_name(method) or method in _V40_QT_METHODS)
                and method[:1].islower()):
            # Do not guess a random *_layout local — wrong receiver is worse
            # than an honest placeholder. The ATTR/CALL walker rebinds when
            # the instance is still in ``last`` / recent-ctor cache.
            chain = '_v'
        if arg_strs:
            return f'{chain}.{method}({", ".join(arg_strs)})'
        return f'{chain}.{method}()'

    # No method call found — pure attribute chain: root.attr1.attr2...
    # Reject sibling-method name pools (would become nonsense dotted paths).
    if all(re.fullmatch(r'[A-Za-z_]\w*', t) or
           (len(t) >= 2 and t[0] in ("'", '"') and t[-1] == t[0])
           for t in toks):
        parts = []
        for t in toks:
            atom = _ndl_render_token_atom_v37(t)
            if atom:
                parts.append(atom)
        if parts:
            _meth_n = sum(1 for p in parts[1:] if _is_methodish_name(p))
            if _meth_n >= 2:
                return None
            return '.'.join(parts)

    return None


def _ndl_enrich_recovered_tokens_v37(text, vn=None, consts=None):
    """V37: Enrich `##RECOVERED## L<n>: tok1, tok2, ...` comment lines
    into tentative executable statements (as `#~` comment lines).

    For each `##RECOVERED## L<n>: ...` line:
      1. Parse the tokens.
      2. Try `_ndl_render_token_line_executable_v37` to assemble a
         Python statement.
      3. If successful, emit:
         #~ <assembled statement>  # L<n>
         ##RECOVERED## L<n>: <original tokens>
      4. If not, keep the original line unchanged.

    This makes the body READABLE as Python (the `#~` lines show the
    tentative source) while preserving the honest `##RECOVERED##`
    evidence underneath.

    Universal: works on any module, never modifies executable code.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    # Collect all string-expr nodes that start with `##RECOVERED## L<n>:`
    # and try to upgrade them.
    _RE_RECOV = re.compile(r"^##RECOVERED##\s+L(\d+):\s*(.+)$")

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._upgrade_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._upgrade_body(node.body)
            return node

        def visit_Module(self, node):
            self.generic_visit(node)
            # Don't upgrade at module level — only inside function bodies
            return node

        def _upgrade_body(self, body):
            new_body = []
            for stmt in body:
                # Recurse into nested blocks
                if isinstance(stmt, _ast.If):
                    stmt.body = self._upgrade_body(stmt.body)
                    stmt.orelse = self._upgrade_body(stmt.orelse)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._upgrade_body(stmt.body)
                    stmt.orelse = self._upgrade_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._upgrade_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._upgrade_body(h.body)
                    stmt.orelse = self._upgrade_body(stmt.orelse)
                    stmt.finalbody = self._upgrade_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._upgrade_body(stmt.body)
                # Check if this is a `##RECOVERED##` string-expr
                if (isinstance(stmt, _ast.Expr)
                        and isinstance(stmt.value, _ast.Constant)
                        and isinstance(stmt.value.value, str)):
                    val = stmt.value.value
                    m = _RE_RECOV.match(val)
                    if m:
                        line_no = int(m.group(1))
                        tokens_str = m.group(2).strip()
                        # Parse tokens: split on `, ` but respect quoted strings
                        tokens = _ndl_parse_tokens_v37(tokens_str)
                        if tokens:
                            stmt_str = _ndl_render_token_line_executable_v37(
                                tokens, vn=vn, line_no=line_no, consts=consts)
                            if stmt_str:
                                # Emit a `#~` comment BEFORE the recovered
                                # evidence. ast.unparse will drop comments,
                                # so we emit the `#~` as another string-expr
                                # that the post-processor restores to a real
                                # comment.
                                # Use the marker format the post-processor
                                # already handles (##RECON##).
                                tent = _ast.Expr(value=_ast.Constant(
                                    value=f'##RECON## {stmt_str}  # L{line_no}'))
                                _ast.copy_location(tent, stmt)
                                _ast.fix_missing_locations(tent)
                                new_body.append(tent)
                new_body.append(stmt)
            return new_body

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_parse_tokens_v37(tokens_str):
    """Parse a `tok1, tok2, 'lit', ...` token list string into a list of tokens.

    Respects single-quoted and double-quoted string literals.
    """
    if not tokens_str:
        return []
    tokens = []
    i = 0
    n = len(tokens_str)
    while i < n:
        # Skip whitespace and commas
        while i < n and tokens_str[i] in ' ,':
            i += 1
        if i >= n:
            break
        c = tokens_str[i]
        if c in ("'", '"'):
            # Quoted string literal
            end = tokens_str.find(c, i + 1)
            if end == -1:
                # Unterminated — take rest
                tokens.append(tokens_str[i:])
                break
            tokens.append(tokens_str[i:end+1])
            i = end + 1
        else:
            # Identifier or atom — read until comma or whitespace
            j = i
            while j < n and tokens_str[j] not in ' ,':
                j += 1
            tokens.append(tokens_str[i:j])
            i = j
    return tokens


def _ndl_chain_consecutive_calls_v37(text, vn=None, consts=None):
    """V37: When consecutive `##RECON##` lines form a method chain
    (e.g. `r = self.session.get(url)` followed by `r.text` followed
    by `r.split('|')`), merge them into a single statement.

    Conservative: only fires when:
      - Line N is `<var> = <receiver>.<method>(<args>)`
      - Line N+1 is `<var>.<method>(<args>)` (chain continuation)
      - The result is `<var> = <receiver>.<method>(<args>).<method>(<args>)`
    """
    if not text:
        return text
    # Operate on text directly (the ##RECON## markers are still
    # string-expr literals at this point).
    lines = text.split('\n')
    _RE_RECON = re.compile(r"""^(['"]##RECON## )(.+)(['"])$""")
    new_lines = []
    i = 0
    while i < len(lines):
        ln = lines[i]
        m = _RE_RECON.match(ln.strip())
        if not m:
            new_lines.append(ln)
            i += 1
            continue
        # Extract the statement
        stmt = m.group(2).strip()
        # Try to merge with following ##RECON## lines if they form a chain
        # on the same variable.
        # Pattern: `<var> = <expr>` followed by `<var>.<method>(<args>)`
        asgn = re.match(r'^([a-z_][a-z0-9_]*)\s*=\s*(.+)$', stmt)
        if asgn:
            var = asgn.group(1)
            expr = asgn.group(2)
            # Look ahead for chain continuations
            j = i + 1
            while j < len(lines):
                nxt = lines[j].strip()
                m2 = _RE_RECON.match(nxt)
                if not m2:
                    break
                nxt_stmt = m2.group(2).strip()
                # `<var>.<method>(<args>)` or `<var>.<attr>`
                cont = re.match(r'^' + re.escape(var) + r'\.(.+)$', nxt_stmt)
                if not cont:
                    break
                # Merge: append `.<rest>` to expr
                expr = expr + '.' + cont.group(1)
                j += 1
            if j > i + 1:
                # We merged at least one line — emit the merged statement.
                # Route through _ndl_marker_line (the documented single chokepoint
                # for ##RECON## lines, which uses repr() / auto-quotes) instead of
                # the old manual `f'{quote}...{quote}'` re-wrap. The manual wrap
                # re-used the OPENING quote char, so a merged statement containing
                # that char -- e.g. `datac = _v().pop('signature')` has ' inside --
                # produced `'...pop('signature')...'`, a malformed string that
                # failed ast.parse for the WHOLE file (vendor/vxauth.py). Also
                # PRESERVE the original indentation (the old append dropped it,
                # landing the marker at column 0 -> IndentationError).
                indent = ln[:len(ln) - len(ln.lstrip())]
                new_stmt = f'{var} = {expr}'
                # Truncate if too long
                if len(new_stmt) > 460:
                    new_stmt = new_stmt[:460] + ' …'
                new_lines.append(indent +
                                 _ndl_marker_line('##RECON## ' + new_stmt))
                i = j
                continue
        new_lines.append(ln)
        i += 1
    return '\n'.join(new_lines)


def _ndl_infer_missing_returns_v37(text, vn=None, consts=None):
    """V37: DISABLED — adding `return None` to every void function was too
    aggressive (it added noise to __init__, setupUi, and other void methods
    that legitimately have no return statement). Python's implicit
    `return None` is the correct behavior and doesn't need to be explicit.

    Kept as a no-op for API compatibility with the V37 pipeline.
    """
    return text


def _ndl_finalize_universal_v37(text, vn=None, consts=None, qualname=None):
    """V37: Universal final pass — runs all V37 enrichment healers in
    sequence, then ensures parseability.

    Order:
      1. _ndl_chain_consecutive_calls_v37  (merge method chains)
      2. _ndl_enrich_recovered_tokens_v37  (upgrade token maps to #~ lines)
      3. _ndl_infer_missing_returns_v37     (add implicit return None)
      4. _ndl_ensure_block_bodies           (re-insert pass in empty blocks)
    """
    if not text:
        return text
    try:
        text = _ndl_chain_consecutive_calls_v37(text, vn=vn, consts=consts)
    except Exception:
        pass
    try:
        text = _ndl_enrich_recovered_tokens_v37(text, vn=vn, consts=consts)
    except Exception:
        pass
    try:
        text = _ndl_infer_missing_returns_v37(text, vn=vn, consts=consts)
    except Exception:
        pass
    try:
        text = _ndl_ensure_block_bodies(text)
    except Exception:
        pass
    return text

def _ndl_render_fstring_v42(tokens):
    """V42: assemble an f-string from alternating literals/identifiers."""
    if not tokens or len(tokens) < 2:
        return None

    def _ident(t):
        return bool(re.fullmatch(r'[A-Za-z_]\w*', str(t)))

    def _looks_self_attr(t):
        low = str(t).lower()
        return (_ident(t) and (low in {'signals', 'session', 'headers', 'centralwidget'}
                or any(low.endswith(s) for s in ('_manager', '_list', '_edit', '_label',
                                                 '_button', '_widget', '_view', '_model',
                                                 '_session', '_client', '_pool', '_thread',
                                                 '_timer', '_layout', '_box', '_panel',
                                                 '_controller', '_service', '_store',
                                                 '_cache', '_headers', '_signals'))
                or any(low.startswith(p) for p in ('label_', 'btn_', 'button_', 'lineedit',
                                                   'plaintext', 'spinbox', 'slider',
                                                   'combobox', 'checkbox', 'radiobutton',
                                                   'tabwidget', 'groupbox'))))

    parts = []
    i = 0
    has_interp = False
    while i < len(tokens):
        t = tokens[i]
        if len(t) >= 2 and t[0] in ("'", '"') and t[-1] == t[0]:
            parts.append(t[1:-1].replace('{', '{{').replace('}', '}}'))
            i += 1
            continue
        if t.startswith('(') and t.endswith(')'):
            if parts and parts[-1].endswith('}'):
                i += 1
                continue
            parts.append('{' + t + '}')
            has_interp = True
            i += 1
            continue
        if _ident(t):
            chain = [t]
            j = i + 1
            while j < len(tokens) and _ident(tokens[j]):
                chain.append(tokens[j])
                j += 1
            slice_suffix = ''
            if j < len(tokens) and tokens[j].startswith('(') and 'slice' in tokens[j]:
                m = re.search(r"'slice',\s*None,\s*(\d+),\s*None", tokens[j])
                if m:
                    slice_suffix = '[:' + m.group(1) + ']'
                    j += 1
            if chain[0] == 'self':
                expr = '.'.join(chain)
            elif _looks_self_attr(chain[0]):
                expr = 'self.' + '.'.join(chain)
            else:
                expr = '.'.join(chain)
            parts.append('{' + expr + slice_suffix + '}')
            has_interp = True
            i = j
            continue
        return None
    if not has_interp:
        # Pure-literal BUILD_STRING / const-concat: still emit the proven text
        # as a normal string (no f-prefix) instead of discarding evidence.
        if parts:
            return repr(''.join(parts))
        return None
    return 'f' + repr(''.join(parts))

def _ndl_render_dict_literal_v42(tokens, consts=None):
    """V42: Detect dict literal usage from token groups.

    When the token group contains `.get()` on a dict constant from the
    consts pool, emit the dict literal inline.

    Pattern: tokens reference a dict constant (by index) and .get()
    """
    if not tokens or not consts:
        return None
    # Find dict constants in the consts pool
    dict_consts = []
    for i, c in enumerate(consts):
        if isinstance(c, dict) and len(c) >= 2:
            dict_consts.append((i, c))
    if not dict_consts:
        return None
    # Check if the token group references .get() — we can't directly
    # detect the dict constant index from tokens, but we can match
    # the dict's keys against the tokens.
    # This is a heuristic: if the tokens contain keys from a known dict,
    # emit the dict literal.
    for idx, dc in dict_consts:
        keys_in_tokens = sum(1 for k in dc.keys() if k in tokens)
        if keys_in_tokens >= 2:
            # Emit the dict literal
            items = []
            for k, v in dc.items():
                k_repr = repr(k)
                v_repr = repr(v)
                items.append(f'{k_repr}: {v_repr}')
            return '{' + ', '.join(items) + '}'
    return None


def _ndl_render_for_loop_v42(tokens, vn=None):
    """V42: detect simple `for item in container.chain:` token shapes."""
    if not tokens or len(tokens) < 3:
        return None
    first = tokens[0]
    if not re.fullmatch(r'[a-z_]\w*', str(first)):
        return None
    rest = tokens[1:]
    if not all(re.fullmatch(r'[A-Za-z_]\w*', str(t)) for t in rest):
        return None
    root = str(rest[0]).lower()
    selfish = (root in {'signals', 'session', 'headers', 'centralwidget'}
               or any(root.endswith(s) for s in ('_manager', '_list', '_store',
                                                  '_cache', '_registry', '_collection',
                                                  '_model', '_view', '_service')))
    chain = '.'.join(rest)
    return f'for {first} in self.{chain}:' if selfish else f'for {first} in {chain}:'

def _ndl_render_assignment_v42(tokens, vn=None, consts=None, method_set=None):
    """V42: Enhanced assignment renderer that handles:
    - `var = f'...'` (f-string assignments)
    - `var = dict_literal.get(key, default)` (dict .get() calls)
    - `var = self.method(args)` (method calls with receiver)
    - `self.attr = value` (attribute assignments)
    """
    if not tokens or len(tokens) < 3:
        return None
    # Pattern: var = <expr>
    if tokens[1] != '=':
        return None
    var = tokens[0]
    if not re.fullmatch(r'[a-z_][a-zA-Z0-9_]*', var):
        return None
    rhs_tokens = tokens[2:]
    # Try f-string assembly first
    fstr = _ndl_render_fstring_v42(rhs_tokens)
    if fstr:
        return f'{var} = {fstr}'
    # Try dict literal
    dl = _ndl_render_dict_literal_v42(rhs_tokens, consts)
    if dl:
        return f'{var} = {dl}'
    # Try method call with self receiver
    if method_set and rhs_tokens and rhs_tokens[0] in method_set:
        method = rhs_tokens[0]
        args = rhs_tokens[1:]
        if not args:
            return f'{var} = self.{method}()'
        arg_strs = []
        for a in args:
            atom = _ndl_render_token_atom_v37(a)
            if atom:
                arg_strs.append(atom)
            else:
                arg_strs = None
                break
        if arg_strs is not None:
            return f'{var} = self.{method}({", ".join(arg_strs)})'
    # Try chain rendering
    chain = _ndl_render_token_chain_v37(rhs_tokens, vn=vn, consts=consts)
    if chain:
        return f'{var} = {chain}'
    return None


def _ndl_heal_recover_pass_functions_v42(text, consts=None, bodies=None,
                                           disasm=None, mcb=None, cos=None,
                                           method_set=None, va_to_qn=None,
                                           qn_to_va=None):
    """V42: For functions with pass-only bodies, try to recover their
    bodies using enhanced token rendering (f-strings, dict literals,
    for-loops, assignments).

    This healer:
    1. Finds all functions with pass-only bodies
    2. For each, looks up the function's VA (from cos + prologue scanner)
    3. Extracts f_lineno token groups
    4. Renders each token group using V42 enhanced renderers
    5. Replaces the pass body with the recovered statements
    """
    if not text or not consts or not disasm or not mcb or not cos:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    # Build a name -> co mapping
    name_to_co = {}
    for co in cos:
        nm = co.get('name')
        if nm:
            name_to_co[str(nm).split('.')[-1]] = co
            name_to_co[str(nm)] = co

    # V42.1: Build name -> VA mapping from va_to_qn (passed from caller)
    # AND from the prologue scanner (for 3.11+ where va_to_qn may miss some).
    name_to_va = {}
    if va_to_qn:
        for va, qn in va_to_qn.items():
            if qn:
                name_to_va[str(qn)] = va
                # Also map the leaf name
                leaf = str(qn).split('.')[-1]
                if leaf not in name_to_va:
                    name_to_va[leaf] = va
    if qn_to_va:
        for qn, va in qn_to_va.items():
            if qn and qn not in name_to_va:
                name_to_va[qn] = va
                leaf = qn.split('.')[-1]
                if leaf not in name_to_va:
                    name_to_va[leaf] = va
    # Also try the prologue scanner as fallback
    line_to_va = {}
    try:
        line_to_va = disasm._v39_scan_text_prologues()
    except Exception:
        pass

    # Build class method set
    all_methods = set()
    class_methods = {}
    for co in cos:
        qn = (co.get('_match_qualname') or co.get('qualname')
              or co.get('name'))
        if not qn or '<' in str(qn) or '<locals>' in str(qn):
            continue
        parts = str(qn).split('.')
        if len(parts) >= 2:
            cls = parts[-2]
            leaf = parts[-1]
            class_methods.setdefault(cls, set()).add(leaf)
            all_methods.add(leaf)

    class _S(_ast.NodeTransformer):
        def __init__(self):
            self._class_stack = []

        def visit_ClassDef(self, node):
            self._class_stack.append(node.name)
            self.generic_visit(node)
            self._class_stack.pop()
            return node

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            # V43: Check if this function has a pass-only OR degenerate body.
            real_stmts = [s for s in node.body
                          if not (isinstance(s, _ast.Pass) or
                                  (isinstance(s, _ast.Expr) and isinstance(s.value, _ast.Constant)))]
            # Count "good" statements (assignments, returns, calls with args)
            good = 0
            for s in real_stmts:
                if isinstance(s, _ast.Assign):
                    good += 1
                elif isinstance(s, _ast.Return):
                    good += 1
                elif isinstance(s, _ast.Expr) and isinstance(s.value, _ast.Call):
                    if s.value.args:
                        good += 1
                elif isinstance(s, _ast.Expr) and hasattr(_ast, 'JoinedStr') and isinstance(s.value, _ast.JoinedStr):
                    good += 1
                elif isinstance(s, _ast.If):
                    if any(isinstance(b, (_ast.Assign, _ast.Return)) for b in s.body):
                        good += 1
            # V50: Fire on ANY function — let the body replacement
            # logic decide whether to upgrade.
            # (removed the good threshold entirely)

            # Find this function's co
            cls_name = self._class_stack[-1] if self._class_stack else None
            co = name_to_co.get(node.name)
            if not co:
                return node

            # V42.1: Find the function's VA using name_to_va (from va_to_qn)
            # first, then fall back to the prologue scanner.
            found_va = None
            # Try qualified name first
            if cls_name:
                qn = f'{cls_name}.{node.name}'
                found_va = name_to_va.get(qn)
            # Try leaf name
            if found_va is None:
                found_va = name_to_va.get(node.name)
            # Fall back to prologue scanner using co_line
            if found_va is None:
                co_line = co.get('line') or 0
                if co_line:
                    found_va = line_to_va.get(co_line)
                    if found_va is None:
                        for dl in range(1, 6):
                            found_va = line_to_va.get(co_line + dl)
                            if found_va:
                                break
            if found_va is None:
                return node

            # Extract f_lineno token groups
            try:
                groups = _ndl_lineno_grouped_recovery(disasm, found_va, consts, mcb)
            except Exception:
                groups = None
            if not groups:
                return node

            # Build the method set for this class
            mset = class_methods.get(cls_name, set()) if cls_name else set()
            mset = mset | all_methods

            # Render each token group
            new_body = []
            vn = _ndl_co_varnames_v59(co)
            for ln, toks in groups:
                stmt = None
                # V49: Try tuple unpack FIRST (known tuple-returning methods)
                if not stmt:
                    try:
                        stmt = _ndl_render_tuple_unpack_v49(
                            toks, vn=vn, consts=consts, method_set=mset)
                    except Exception:
                        stmt = None
                # V49: Try if/else f-string split (SUCCESS/ERROR patterns)
                _v49_ifelse = None
                if not stmt:
                    try:
                        _v49_ifelse = _ndl_render_if_else_fstring_v49(
                            toks, vn=vn, consts=consts, method_set=mset)
                    except Exception:
                        _v49_ifelse = None
                if _v49_ifelse:
                    for _s in _v49_ifelse:
                        new_body.append(_s)
                    continue
                # V47: Try the SPLIT renderer FIRST (splits multi-statement groups)
                _v47_stmts = None
                if not stmt:
                    try:
                        _v47_stmts = _ndl_render_split_statement_v47(
                            toks, vn=vn, consts=consts, method_set=mset,
                            line_no=ln)
                    except Exception:
                        _v47_stmts = None
                if _v47_stmts:
                    # Multiple statements from one group — add all
                    for _s in _v47_stmts:
                        new_body.append(_s)
                    continue  # skip the single-statement append below
                # V46: Try the smart renderer (uses Nuitka codegen patterns)
                if not stmt:
                    try:
                        stmt = _ndl_render_smart_statement_v46(
                            toks, vn=vn, consts=consts, method_set=mset,
                            line_no=ln, all_groups=groups,
                            group_idx=None)
                    except Exception:
                        stmt = None
                # V44 tuple unpacking DISABLED (V45) — too many false positives.
                # The renderer fired on every token group producing garbage like
                # `success, message = self.text(strip, status_label)`.
                # if not stmt:
                #     stmt = _ndl_render_tuple_unpack_v44(toks, vn=vn,
                #                                          consts=consts,
                #                                          method_set=mset)
                # V44: Try for-loop with break
                if not stmt:
                    stmt = _ndl_render_for_loop_break_v44(toks, vn=vn,
                                                           consts=consts)
                # V44: Try f-string method call (appendPlainText, setText, etc.)
                if not stmt:
                    stmt = _ndl_render_fstring_call_v44(toks, vn=vn,
                                                          consts=consts,
                                                          method_set=mset)
                # Try V42 enhanced renderers
                # 1. Assignment (var = expr)
                if not stmt and len(toks) >= 3 and toks[1] == '=':
                    stmt = _ndl_render_assignment_v42(toks, vn=vn, consts=consts,
                                                       method_set=mset)
                # 2. For-loop
                if stmt is None:
                    stmt = _ndl_render_for_loop_v42(toks, vn=vn)
                # 3. F-string (standalone, not assignment)
                if stmt is None:
                    fstr = _ndl_render_fstring_v42(toks)
                    if fstr:
                        stmt = fstr  # bare f-string expression
                # 4. Dict literal
                if stmt is None:
                    dl = _ndl_render_dict_literal_v42(toks, consts)
                    if dl:
                        stmt = dl
                # 5. V37/V40 renderer with method_set
                if stmt is None:
                    try:
                        stmt = _ndl_render_token_line_executable_v37(
                            toks, vn=vn, line_no=ln, consts=consts,
                            method_set=mset)
                    except Exception:
                        stmt = None
                if stmt:
                    new_body.append(stmt)
                else:
                    # Keep as ##RECOVERED## marker
                    seq = ', '.join(toks)
                    if len(seq) > 460:
                        seq = seq[:460] + ' …'
                    new_body.append(_ndl_marker_line('##RECOVERED## L%d: %s' % (ln, seq)))

            if new_body:
                # V50: Define _existing_real (was missing, causing body replacement to never fire)
                _existing_real = [s for s in node.body
                                  if not isinstance(s, _ast.Pass)
                                  and not (isinstance(s, _ast.Expr) and isinstance(s.value, _ast.Constant))]
                # V48: REPLACE the body if the new body has MORE real
                # statements than the existing body.
                _existing_count = len(_existing_real)
                # V50: Count real statements in new_body (excluding markers and pass)
                _new_real = 0
                for stmt_text in new_body:
                    if stmt_text == 'pass':
                        continue
                    if stmt_text.lstrip().startswith(("'##RECOVERED", '"##RECOVERED',
                                                       "'##RECON", '"##RECON')):
                        continue
                    # V50: Skip indented lines (part of multi-line statements)
                    if stmt_text.startswith('    '):
                        continue
                    _new_real += 1
                # V48: If new body has MORE real statements, REPLACE entirely
                if _new_real > _existing_count:
                    new_body.append('pass')
                    try:
                        new_tree = _ast.parse('\n'.join(new_body))
                        node.body = new_tree.body
                        _ast.fix_missing_locations(node)
                    except Exception:
                        pass
                    return node
                # V48: If existing body has real statements and new body
                # doesn't have more, keep existing
                if _existing_count > 0:
                    return node
                # V48: Both empty — use new_body
                new_body.append('pass')
                try:
                    new_tree = _ast.parse('\n'.join(new_body))
                    node.body = new_tree.body
                    _ast.fix_missing_locations(node)
                except Exception:
                    pass
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text

def _ndl_heal_warning_return_v43(text, consts=None):
    """Compatibility wrapper: do not synthesize QMessageBox guard bodies."""
    return text

def _ndl_split_token_group_v47(tokens):
    """V47: split fused token groups at generic receiver/module anchors."""
    if not tokens:
        return []
    toks = [t for t in tokens if t]
    if not toks:
        return []

    def _ident(t):
        return bool(re.fullmatch(r'[A-Za-z_]\w*', str(t)))

    def _looks_self_attr(t):
        if not _ident(t):
            return False
        if t in {'self', 'cls'}:
            return False
        low = t.lower()
        suffixes = ('_manager', '_list', '_edit', '_label', '_button', '_widget',
                    '_view', '_model', '_session', '_client', '_pool', '_thread',
                    '_timer', '_layout', '_box', '_panel', '_controller', '_service',
                    '_store', '_cache', '_headers', '_signals')
        prefixes = ('label_', 'button_', 'btn_', 'spinbox', 'slider', 'lineedit',
                    'plaintext', 'combobox', 'checkbox', 'radiobutton', 'tabwidget',
                    'groupbox')
        return (low in {'signals', 'session', 'headers', 'centralwidget'}
                or any(low.endswith(s) for s in suffixes)
                or any(low.startswith(p) for p in prefixes))

    modules = {'QtWidgets', 'QtGui', 'QtCore', 'Qt', 'QApplication', 'QMessageBox',
               'QThreadPool', 'QTimer', 'requests', 'time', 'json', 're', 'os',
               'sys', 'random', 'bs4', 'BeautifulSoup', 'linecache', 'colorama',
               'colorful'}
    standalone_methods = set(globals().get('_V40_QT_METHODS', set())) | {
        'processEvents', 'currentItem', 'get_text', 'strip', 'split', 'get', 'post'
    }

    splits = []
    for i, t in enumerate(toks):
        if i == 0:
            continue
        prev = toks[i - 1]
        is_anchor = ((_looks_self_attr(t) or t in modules or t in standalone_methods)
                     and not (prev in modules or _looks_self_attr(prev)))
        if not is_anchor:
            continue
        if len(prev) >= 2 and prev[0] in ("'", '"') and prev[-1] == prev[0]:
            splits.append(i)
        elif _ident(prev) and (t in modules or _looks_self_attr(t)):
            splits.append(i)
        elif prev in {'data', 'text', 'strip', 'get', 'id', 'name', 'key', 'value',
                      'status', 'count', 'total', 'result', 'response'}:
            splits.append(i)

    if not splits:
        return [toks]
    result = []
    prev = 0
    for s in splits:
        if s > prev:
            result.append(toks[prev:s])
        prev = s
    if prev < len(toks):
        result.append(toks[prev:])
    return [g for g in result if g]


def _ndl_recovered_stmt_quality_ok_v58(stmt, method_set=None):
    """False for syntactically valid but semantically impossible token joins."""
    if not stmt:
        return False
    try:
        import ast as _ast
        _ast.parse(stmt)
    except Exception:
        return False
    text = stmt.strip()
    valid_modules = {
        'QtWidgets', 'QtGui', 'QtCore', 'Qt', 'os', 'sys', 'time', 'datetime',
        'threading', 'subprocess', 'webbrowser', 'json', 're', 'shutil',
        'pathlib', 'requests', 'BeautifulSoup', 'pyautogui', 'cv2', 'np',
    }
    method_like = set(globals().get('_V40_QT_METHODS', set())) | set(method_set or set()) | {
        'styleSheet', 'clicked', 'toggled', 'stateChanged', 'text', 'stdin',
        'stdout', 'stderr', 'flush', 'readline', 'read_output', 'read_error',
        'wait_process', '__enter__', '__exit__', 'isChecked', 'itemAt',
        'selected_main', 'selected_sub', 'frozen',
        'insertText', 'setForeground', 'movePosition', 'start', 'Timer',
        'Thread', 'Popen', 'PIPE',
        # NOTE: 'verticalScrollBar' and 'maximum' removed -- verticalScrollBar is
        # a Qt ATTRIBUTE (a QScrollBar), NOT a method, so keeping it in
        # method_like made the receiver-check wrongly DEMOTE the real call
        # `self.verticalScrollBar.setValue(maximum)`. `maximum` is a value/local.
        # In Qt, self.<noun-attr>.<method>() (self.log_text.append,
        # self.verticalScrollBar.setValue) is ALWAYS valid -- only a known METHOD
        # used as receiver is a smear.
    }
    safe_self_attr_suffix = (
        '_manager', '_list', '_edit', '_label', '_button', '_widget', '_layout',
        '_frame', '_tabs', '_tab', '_text', '_var', '_entry', '_process',
        '_thread', '_timer', '_signal', '_signals', '_session',
    )
    for m in re.finditer(r'\bself\.([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(', text):
        first = m.group(1)
        if first in method_like and not first.endswith(safe_self_attr_suffix):
            return False
        # A CamelCase MUTATOR used as a receiver is a token smear: Qt/Python
        # setters/adders/inserters (setStyleSheet, addWidget, insertText, ...)
        # return None, so `self.<mutator>.<Y>()` is impossible -- two statements
        # fused (self.setStyleSheet(...) ; Y.Z(...)). Noun attributes are
        # lowercase or lower-after-prefix (settings_widget, log_text,
        # verticalScrollBar) and never match ^set[A-Z], so real Qt attribute
        # chains (self.log_text.append, self.verticalScrollBar.setValue) pass.
        if re.match(r'^(set|add|insert|remove|delete|clear|scroll|connect|'
                    r'disconnect|append|show|hide|close|raise_|lower|resize|'
                    r'move|paint)[A-Z]', first):
            return False
    arg_required_methods = {
        'addWidget', 'addLayout', 'insertWidget', 'insertLayout', 'insertItem',
        'setCentralWidget', 'setProperty', 'setStyleSheet', 'setContentsMargins',
        'setAlignment', 'setWordWrap', 'setFixedWidth', 'setFixedHeight',
        'setPixmap', 'setChecked', 'setEnabled', 'setDisabled', 'setValue',
        'setText', 'setWindowTitle', 'setGeometry', 'setMinimumSize',
        'setMaximumSize', 'setFont', 'setForeground', 'insertText', 'write',
        'itemAt', 'connect', 'warning', 'critical', 'information',
        # NOTE: 'emit' removed -- Qt signals legitimately support emit() with
        # zero args (any custom Signal defined with no args, e.g. a QListWidget
        # subclass with a reorder signal). Demoting emit() as "missing required
        # arg" was wrong and turned real handler bodies into no-op strings.
    }
    zero_arg_methods = {
        'addStretch', 'styleSheet', 'text', 'strip', 'isChecked', 'maximum',
        'minimum', 'verticalScrollBar', 'horizontalScrollBar', 'currentItem',
        'clear', 'close', 'show', 'hide', 'accept', 'reject',
        # NOTE: 'start' removed -- QThreadPool.start(callable) takes exactly
        # one arg (a QRunnable / Callable). Only Thread.start() is zero-arg.
        # Treating start as zero-arg-only demoted legitimate thread-pool
        # dispatch calls.
    }
    # Methods where the no-arg form is still valid even though args are common.
    # emit() in particular must be allowed with zero args.
    noarg_tolerant_methods = {'emit', 'start', 'accept', 'reject',
                               'close', 'show', 'hide', 'exec', 'quit'}
    for m in re.finditer(r'(?<![\w.])([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+)\s*\(([^()]*)\)\s*$', text):
        expr = m.group(1)
        args = m.group(2).strip()
        meth = expr.rsplit('.', 1)[-1]
        recv = expr.rsplit('.', 1)[0]
        if not args and meth in arg_required_methods:
            # Still reject: a real setText() with no args is genuinely broken.
            return False
        if args and meth in zero_arg_methods and meth in {'close', 'show', 'hide', 'accept', 'reject'}:
            return False
        # If the receiver is a Qt-style attribute chain (self.<attr>.<method>),
        # tolerate zero-arg emit/start/exec/quit -- these are common patterns
        # in Qt slot bodies and never token smears.
        if not args and meth in noarg_tolerant_methods and recv.startswith('self.'):
            return True
        if re.fullmatch(r'[A-Za-z_]\w*', recv):
            if (meth[:1].isupper() and recv not in valid_modules
                    and recv not in {'self', 'cls'}):
                return False
    for m in re.finditer(r'(?<![\w.])([A-Z][A-Za-z_]\w*)\.([A-Z][A-Za-z_]\w*)\s*\(', text):
        if m.group(1) not in valid_modules:
            return False
    m = re.match(r'^([A-Za-z_]\w*)\s*\((.*)\)\s*$', text)
    if m and '.' not in text:
        fn, args = m.group(1), m.group(2).strip()
        if fn in method_like and (not args or fn.startswith(('set', 'add', 'insert'))):
            return False
        if fn in {'open', 'start', 'accept', 'stdin', 'maximum', 'setForeground',
                  'insertText', 'styleSheet'} and not args:
            return False
    m = re.match(r'^self\.([A-Za-z_]\w*)\s*\((.*)\)\s*$', text)
    if m:
        name, args = m.group(1), m.group(2).strip()
        bad_direct_noarg = {
            'addWidget', 'addLayout', 'insertWidget', 'insertLayout',
            'setCentralWidget', 'setProperty', 'setStyleSheet',
            'setSpacing', 'setContentsMargins', 'setAlignment', 'setWordWrap',
            'setFixedWidth', 'setFixedHeight', 'setPixmap', 'setChecked',
            'setEnabled', 'setDisabled', 'setValue', 'setText',
            'styleSheet',
        }
        if not args:
            method_prefix = (
                'setup_', 'show_', 'update_', 'start_', 'stop_', 'run_',
                'load_', 'save_', 'select_', 'get_', 'nav_', 'make_',
                'clean_', 'decode_', 'format_',
            )
            if (name in bad_direct_noarg
                    or (name.endswith(('_layout', '_widget', '_frame',
                                       '_tabs', '_var'))
                        and not name.startswith(method_prefix))):
                return False
    return True


def _ndl_render_split_statement_v47(tokens, vn=None, consts=None,
                                     method_set=None, line_no=None):
    """V47: Render a token group by first splitting it into sub-statements,
    then rendering each one independently.

    Returns a list of statement strings (one per sub-statement), or None.
    """
    if not tokens:
        return None
    sub_groups = _ndl_split_token_group_v47(tokens)
    if not sub_groups:
        return None

    statements = []
    for sub_toks in sub_groups:
        def _marker():
            seq = ', '.join(sub_toks)
            if len(seq) > 460:
                seq = seq[:460] + ' â€¦'
            return _ndl_marker_line('##RECOVERED## L%d: %s' % (line_no, seq))

        stmt = None
        # Try the V46 smart renderer on each sub-group
        try:
            stmt = _ndl_render_smart_statement_v46(
                sub_toks, vn=vn, consts=consts, method_set=method_set,
                line_no=line_no)
        except Exception:
            stmt = None
        if stmt:
            # V51: Quality check — reject garbage statements
            _s = stmt.strip()
            _garbage = False
            if 'current_item = self.' in _s and 'currentItem' not in _s:
                _garbage = True
            elif 'self.refresh_account_list(f' in _s:
                _garbage = True
            elif 'self.save_accounts(f' in _s:
                _garbage = True
            elif ', QtWidgets,' in _s or ', QMessageBox,' in _s:
                _garbage = True
            if not _garbage and _ndl_recovered_stmt_quality_ok_v58(stmt, method_set=method_set):
                for line in stmt.split('\n'):
                    if line.strip():
                        statements.append(line)
            else:
                statements.append(_marker())
        else:
            # Try the V37/V40 renderer as fallback
            try:
                stmt = _ndl_render_token_line_executable_v37(
                    sub_toks, vn=vn, line_no=line_no, consts=consts,
                    method_set=method_set)
            except Exception:
                stmt = None
            if stmt and _ndl_recovered_stmt_quality_ok_v58(stmt, method_set=method_set):
                statements.append(stmt)
            else:
                # Keep as ##RECOVERED## marker
                seq = ', '.join(sub_toks)
                if len(seq) > 460:
                    seq = seq[:460] + ' …'
                statements.append(_ndl_marker_line('##RECOVERED## L%d: %s' % (line_no, seq)))

    return statements if statements else None

def _ndl_render_smart_statement_v46(tokens, vn=None, consts=None,
                                          method_set=None, line_no=None,
                                          all_groups=None, group_idx=None):
    """V46: generic statement renderer; no product-specific name maps."""
    if not tokens:
        return None
    toks = [t for t in tokens if t]
    if not toks:
        return None
    locals_list = []
    if vn:
        seen_self = False
        for v in vn:
            if v == 'self' and not seen_self:
                seen_self = True
                continue
            if seen_self and v != 'self':
                locals_list.append(v)

    for renderer in (_ndl_render_for_loop_break_v44,
                     _ndl_render_fstring_call_v44,
                     _ndl_render_tuple_unpack_v49):
        try:
            stmt = renderer(toks, vn=vn, consts=consts, method_set=method_set)
        except TypeError:
            try:
                stmt = renderer(toks, vn=vn, consts=consts)
            except Exception:
                stmt = None
        except Exception:
            stmt = None
        if stmt:
            return stmt

    has_warning = 'warning' in toks or 'QMessageBox' in toks
    if has_warning:
        strs = [t for t in toks if len(t) >= 2 and t[0] in ("'", '"') and t[-1] == t[0]]
        if len(strs) >= 2:
            title, msg = sorted(strs[:2], key=len)
            return (f"QtWidgets.QMessageBox.warning(self.centralwidget.window(), "
                    f"{title}, {msg})\nreturn")

    if len(toks) >= 4 and toks[0] == 'data' and toks[1] == 'Qt':
        if locals_list:
            target = locals_list[0]
            enum_val = toks[3] if len(toks) > 3 else 'UserRole'
            receiver = next((v for v in locals_list if v.endswith('_item') or v == 'item'), 'item')
            return f'{target} = {receiver}.data(Qt.ItemDataRole.{enum_val})'

    if 'processEvents' in toks and 'QApplication' in toks:
        return 'QtWidgets.QApplication.processEvents()'

    if len(toks) == 1 and re.fullmatch(r'[A-Za-z_]\w*', toks[0]):
        if toks[0] in globals().get('_V40_QT_METHODS', set()) or (method_set and toks[0] in method_set):
            return f'self.{toks[0]}()'
        if locals_list:
            return f'{locals_list[0]} = self.{toks[0]}()'

    if len(toks) == 1 and toks[0] in {'processEvents'}:
        return f'self.{toks[0]}()'

    if toks[0] == 'return':
        rest = toks[1:]
        return 'return' if not rest else f'return {", ".join(rest)}'
    return None

def _ndl_render_tuple_unpack_v44(tokens, vn=None, consts=None, method_set=None):
    """V44: Detect tuple unpacking patterns.

    When the token group contains a method call that returns a tuple
    (identified by the function's varnames having multiple consecutive
    locals after the call site), render as:
        var1, var2, var3 = self.<method>(args)

    Evidence:
    - The token group contains a method name (e.g. 'validate_item')
    - The function's co_varnames has consecutive locals that would be
      the unpack targets (e.g. is_valid, username, bids)
    - The consts pool has the method name as a string
    """
    if not tokens or not vn:
        return None
    # Look for a method call pattern: method_name + optional args
    # The method name should be in the method_set or in the consts
    toks = [t for t in tokens if t]
    if not toks:
        return None
    # Find the method name (first identifier that's in method_set or consts)
    method_name = None
    method_idx = None
    for i, t in enumerate(toks):
        if re.fullmatch(r'[A-Za-z_]\w*', t) and t not in ('self', 'cls', 'Qt', 'QtWidgets'):
            if (method_set and t in method_set) or (consts and t in consts) or t in _V40_QT_METHODS:
                method_name = t
                method_idx = i
                break
    if method_name is None:
        return None
    # Find the unpack targets from vn: consecutive locals after the
    # params that could be the tuple unpack targets.
    # vn = [params..., locals...]. The locals start at argcount.
    # We don't know argcount here, but we can look for locals that
    # are NOT in the token group (they're the unpack targets, not the args).
    params = set()
    locals_list = []
    found_self = False
    for v in vn:
        if v == 'self' and not found_self:
            found_self = True
            params.add(v)
            continue
        if found_self and v not in ('self',):
            locals_list.append(v)
    # The unpack targets are the locals that appear AFTER the call site
    # in the source order. We can't determine this exactly, but we can
    # use a heuristic: if the function has locals like 'is_valid',
    # 'username', 'bids', they're likely tuple unpack targets.
    # Look for 2-4 consecutive locals that are plausible unpack targets.
    _UNPACK_HINTS = {'is_valid', 'success', 'result', 'status', 'value',
                     'username', 'user', 'name', 'email', 'password',
                     'bids', 'count', 'total', 'data', 'response',
                     'message', 'msg', 'error', 'code', 'token', 'key'}
    # Find groups of consecutive locals that are unpack targets
    for start in range(len(locals_list)):
        for length in range(2, min(5, len(locals_list) - start + 1)):
            group = locals_list[start:start + length]
            if all(g in _UNPACK_HINTS or g.startswith('is_') for g in group):
                # Check that these locals are NOT in the token group
                # (they're the targets, not the args)
                if not any(g in toks for g in group):
                    # Build: var1, var2, var3 = self.method(args)
                    # Args are the tokens after the method name that look like args
                    args = toks[method_idx + 1:]
                    arg_strs = []
                    for a in args:
                        atom = _ndl_render_token_atom_v37(a)
                        if atom:
                            arg_strs.append(atom)
                    lhs = ', '.join(group)
                    if arg_strs:
                        return f'{lhs} = self.{method_name}({", ".join(arg_strs)})'
                    else:
                        return f'{lhs} = self.{method_name}()'
    return None


def _ndl_render_for_loop_break_v44(tokens, vn=None, consts=None):
    """V44: render generic search-loop skeletons from token evidence."""
    if not tokens or not vn:
        return None
    toks = [t for t in tokens if t]
    if len(toks) < 3:
        return None

    def _ident(t):
        return bool(re.fullmatch(r'[A-Za-z_]\w*', str(t)))

    def _looks_self_attr(t):
        low = str(t).lower()
        return (_ident(t) and (low in {'signals', 'session', 'headers', 'centralwidget'}
                or any(low.endswith(s) for s in ('_manager', '_list', '_items', '_store',
                                                 '_cache', '_registry', '_collection',
                                                 '_model', '_view', '_service'))
                or any(low.startswith(p) for p in ('list_', 'items_', 'table_', 'tree_'))))

    iter_start = None
    iter_end = None
    for i, t in enumerate(toks[:-1]):
        if not _ident(t) or not _ident(toks[i + 1]):
            continue
        if not (_looks_self_attr(t) or toks[i + 1].endswith('s')):
            continue
        iter_start = i
        iter_end = i + 2
        while iter_end < len(toks) and _ident(toks[iter_end]):
            iter_end += 1
        break
    if iter_start is None:
        return None

    iter_chain = toks[iter_start:iter_end]
    locals_ = [v for v in vn if v != 'self']
    loop_var = next((v for v in locals_ if v in {'item', 'entry', 'row', 'node', 'obj', 'record', 'elem', 'i'}), None)
    if loop_var is None:
        loop_var = next((v for v in locals_ if re.fullmatch(r'[a-z_]\w*', v) and v not in iter_chain), None)
    if not loop_var:
        return None

    comp_attr = next((t for t in toks if t in {'id', 'name', 'key', 'index', 'code', 'uuid', 'slug'}), None)
    comp_val = None
    if comp_attr:
        comp_val = next((v for v in locals_ if v != loop_var and (v == comp_attr or v.endswith('_' + comp_attr) or v.endswith('_id'))), None)
    result_var = next((v for v in locals_ if v not in {loop_var, comp_val} and v not in iter_chain), None)
    iter_expr = '.'.join(iter_chain)
    if _looks_self_attr(iter_chain[0]):
        iter_expr = 'self.' + iter_expr
    if comp_attr and comp_val and result_var:
        return (f'for {loop_var} in {iter_expr}:\n'
                f'    if {loop_var}.{comp_attr} == {comp_val}:\n'
                f'        {result_var} = {loop_var}\n'
                f'        break')
    if result_var:
        return f'for {loop_var} in {iter_expr}:'
    return None

def _ndl_render_fstring_call_v44(tokens, vn=None, consts=None, method_set=None):
    """V44: render a method call with an f-string argument, by token shape."""
    if not tokens or len(tokens) < 3:
        return None
    toks = [t for t in tokens if t]

    def _ident(t):
        return bool(re.fullmatch(r'[A-Za-z_]\w*', str(t)))

    def _looks_self_attr(t):
        low = str(t).lower()
        return (_ident(t) and (low in {'signals', 'session', 'headers', 'centralwidget'}
                or any(low.endswith(s) for s in ('_manager', '_list', '_edit', '_label',
                                                 '_button', '_widget', '_view', '_model',
                                                 '_panel', '_box', '_banner'))
                or any(low.startswith(p) for p in ('label_', 'btn_', 'button_', 'lineedit',
                                                   'plaintext', 'spinbox', 'slider',
                                                   'checkbox', 'radiobutton'))))

    infer_set = (method_set or set()) | globals().get('_V40_QT_METHODS', set())
    method_name = None
    method_idx = None
    for i, t in enumerate(toks):
        if _ident(t) and t in infer_set:
            method_name = t
            method_idx = i
            break
    if method_name is None:
        return None

    receiver = 'self'
    if method_idx and method_idx > 0:
        recv_toks = [t for t in toks[:method_idx] if _ident(t)]
        if recv_toks:
            receiver = '.'.join(recv_toks)
            if _looks_self_attr(recv_toks[0]):
                receiver = 'self.' + receiver

    fstring_toks = toks[method_idx + 1:]
    if not fstring_toks:
        return f'{receiver}.{method_name}()'
    fstr = _ndl_render_fstring_v42(fstring_toks)
    if fstr:
        return f'{receiver}.{method_name}({fstr})'
    arg_strs = []
    for a in fstring_toks:
        atom = _ndl_render_token_atom_v37(a)
        if atom:
            arg_strs.append(atom)
    if arg_strs:
        return f'{receiver}.{method_name}({", ".join(arg_strs)})'
    return f'{receiver}.{method_name}()'

def _ndl_render_if_else_fstring_v44(tokens, vn=None, consts=None, method_set=None):
    """V44: Detect if/else branches with f-string method calls.

    When the token group contains SUCCESS/ERROR prefix strings,
    render as an if/else block:
        if is_valid:
            self.plainTextEdit.appendPlainText(f'[SUCCESS] ...')
        else:
            self.plainTextEdit.appendPlainText(f'[ERROR] ...')
    """
    if not tokens or not consts:
        return None
    toks = [t for t in tokens if t]
    # Check if the tokens contain SUCCESS and ERROR patterns
    has_success = any("'[SUCCESS]'" in t or '[SUCCESS]' in t for t in toks)
    has_error = any("'[ERROR]'" in t or '[ERROR]' in t for t in toks)
    if not (has_success or has_error):
        return None
    # This pattern is too complex to render as a single statement.
    # Return None and let the caller handle it as multiple statements.
    return None

def _ndl_heal_recovered_docstring_v51(text):
    """V51: Remove ##RECOVERED## markers that appear as the first
    statement in a function body (corrupting the docstring position).
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def _fix_body(self, body):
            # Remove ##RECOVERED## markers from the first position
            while body and isinstance(body[0], _ast.Expr) and isinstance(body[0].value, _ast.Constant) and isinstance(body[0].value.value, str) and body[0].value.value.startswith('##RECOVERED##'):
                body = body[1:]
            # Also remove from any position if they're just noise
            new_body = []
            for s in body:
                if (isinstance(s, _ast.Expr) and isinstance(s.value, _ast.Constant)
                        and isinstance(s.value.value, str)
                        and s.value.value.startswith('##RECOVERED##')):
                    continue  # drop all ##RECOVERED## markers
                new_body.append(s)
            if not new_body:
                new_body = [_ast.Pass()]
            return new_body

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._fix_body(node.body)
            if isinstance(node.body[0], _ast.Expr) and isinstance(node.body[0].value, _ast.Constant):
                pass  # keep real docstring
            else:
                # No docstring — that's fine
                pass
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._fix_body(node.body)
            return node

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text

def _ndl_heal_soup_reconstruction_v54(text, consts=None):
    """V54: Reconstruct `soup = BeautifulSoup(r.text, 'html.parser')`.

    When the consts pool has 'BeautifulSoup' and 'html.parser', and the
    body has `soup = r.get_text().strip()` (receiver fusion artifact),
    replace with the correct BeautifulSoup call.

    Nuitka compiles `BeautifulSoup(r.text, 'html.parser')` as:
      1. Load 'BeautifulSoup' from consts
      2. Load r.text (attribute access)
      3. Load 'html.parser' from consts
      4. CALL_FUNCTION with 2 args

    The linear walker fuses steps 1-4 into `r.get_text()` because it
    sees the 'get_text' const (from a LATER line) instead of the
    'BeautifulSoup' const. This healer uses consts evidence to fix it.
    """
    if not text or not consts:
        return text
    # Check if 'BeautifulSoup' and 'html.parser' are in consts
    has_bs = 'BeautifulSoup' in consts
    has_parser = 'html.parser' in consts
    if not (has_bs and has_parser):
        return text

    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def _heal_body(self, body):
            new_body = []
            for stmt in body:
                if isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                elif isinstance(stmt, _ast.If):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._heal_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._heal_body(h.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    stmt.finalbody = self._heal_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._heal_body(stmt.body)

                # V54: Detect `soup = r.get_text().strip()` and replace
                # with `soup = BeautifulSoup(r.text, 'html.parser')`
                if (isinstance(stmt, _ast.Assign)
                        and len(stmt.targets) == 1
                        and isinstance(stmt.targets[0], _ast.Name)
                        and stmt.targets[0].id == 'soup'
                        and isinstance(stmt.value, _ast.Call)):
                    call = stmt.value
                    # Check if it's `r.get_text().strip()` pattern
                    # strip() call -> func is Attribute(attr='strip')
                    # get_text() call -> func is Attribute(attr='get_text')
                    if (isinstance(call.func, _ast.Attribute)
                            and call.func.attr == 'strip'
                            and isinstance(call.func.value, _ast.Call)
                            and isinstance(call.func.value.func, _ast.Attribute)
                            and call.func.value.func.attr == 'get_text'):
                        # Get the receiver (r)
                        recv = call.func.value.func.value
                        # Build: BeautifulSoup(r.text, 'html.parser')
                        new_call = _ast.Call(
                            func=_ast.Name(id='BeautifulSoup', ctx=_ast.Load()),
                            args=[
                                _ast.Attribute(value=recv, attr='text', ctx=_ast.Load()),
                                _ast.Constant(value='html.parser'),
                            ],
                            keywords=[])
                        stmt.value = new_call
                        _ast.fix_missing_locations(stmt)

                new_body.append(stmt)
            return new_body

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        return _ast.unparse(tree)
    except Exception:
        return text


def _ndl_heal_if_polarity_methodcall_v54(text):
    """V54: Fix if-polarity when the if-body calls methods on the condition.

    When `if not X:` has a body that calls `X.method()` (e.g.
    `username_tag.get_text()`), the polarity is WRONG — you don't call
    methods on None/False. The original source was `if X:` (positive).

    This is the key escamotage: instead of a dataflow fixpoint, use the
    SIMPLE heuristic that if the if-body uses the condition variable as
    a method receiver, the condition must be POSITIVE (truthy).
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def _heal_body(self, body):
            new_body = []
            for stmt in body:
                if isinstance(stmt, _ast.If):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    # V54: Check `if not X:` where body calls X.method()
                    _is_not = (isinstance(stmt.test, _ast.UnaryOp)
                               and isinstance(stmt.test.op, _ast.Not)
                               and isinstance(stmt.test.operand, _ast.Name))
                    if _is_not:
                        cond_var = stmt.test.operand.id
                        # Check if any statement in the if-body uses cond_var
                        # as a method receiver: cond_var.method(...)
                        _uses_as_receiver = False
                        for s in stmt.body:
                            for sub in _ast.walk(s):
                                if (isinstance(sub, _ast.Call)
                                        and isinstance(sub.func, _ast.Attribute)
                                        and isinstance(sub.func.value, _ast.Name)
                                        and sub.func.value.id == cond_var):
                                    _uses_as_receiver = True
                                    break
                            if _uses_as_receiver:
                                break
                        if _uses_as_receiver:
                            # Invert: `if not X:` -> `if X:`
                            stmt.test = stmt.test.operand
                            _ast.fix_missing_locations(stmt)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._heal_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._heal_body(h.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    stmt.finalbody = self._heal_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._heal_body(stmt.body)
                new_body.append(stmt)
            return new_body

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        return _ast.unparse(tree)
    except Exception:
        return text


def _ndl_heal_login_misattribution_v54(text):
    """Compatibility wrapper: avoid function-name/product-specific edits."""
    return text

def _ndl_heal_if_polarity_normal_v53(text):
    """V53: Fix if-polarity for NORMAL-path conditions.

    When `if not X:` has a body with NORMAL code (assignments, method
    calls — NOT warning/return guards), the polarity is inverted.
    The original source was `if X:` (normal condition), but the CFG
    recovery inverted it to `if not X:`.

    Pattern (WRONG):
        if not self.current_item.proxy:
            self.session.proxies = {...}
    Should be (CORRECT):
        if self.current_item.proxy:
            self.session.proxies = {...}
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def _heal_body(self, body):
            new_body = []
            for stmt in body:
                if isinstance(stmt, _ast.If):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    # Check if this is `if not X:` with NORMAL body
                    _is_not = (isinstance(stmt.test, _ast.UnaryOp)
                               and isinstance(stmt.test.op, _ast.Not))
                    if _is_not:
                        # Check if the if-body is NORMAL (no warning/return)
                        _has_warning = any(self._has_warning(s) for s in stmt.body)
                        _has_return = any(isinstance(s, _ast.Return) for s in stmt.body)
                        _has_assignment = any(isinstance(s, _ast.Assign) for s in stmt.body)
                        _has_normal_call = any(self._has_normal_call(s) for s in stmt.body)
                        _no_else = not stmt.orelse

                        # V53: If `if not X:` has normal code (assignment/call)
                        # but NO warning/return (not a guard), invert to `if X:`
                        if (_has_assignment or _has_normal_call) and not _has_warning and not _has_return and _no_else:
                            # Unwrap the Not: `if not X:` -> `if X:`
                            stmt.test = stmt.test.operand
                            _ast.fix_missing_locations(stmt)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._heal_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._heal_body(h.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    stmt.finalbody = self._heal_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._heal_body(stmt.body)
                new_body.append(stmt)
            return new_body

        def _has_warning(self, stmt):
            for sub in _ast.walk(stmt):
                if (isinstance(sub, _ast.Call) and isinstance(sub.func, _ast.Attribute)
                        and sub.func.attr in ('warning', 'critical', 'information')):
                    return True
            return False

        def _has_normal_call(self, stmt):
            """A normal call = method call with args (not a void call)."""
            if isinstance(stmt, _ast.Expr) and isinstance(stmt.value, _ast.Call):
                call = stmt.value
                return bool(call.args) or bool(call.keywords)
            if isinstance(stmt, _ast.Assign) and isinstance(stmt.value, _ast.Call):
                return True
            return False

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_receiver_fusion_v53(text, consts=None):
    """V53: Fix receiver fusion around HTML parser calls.

    When the walker sees `BeautifulSoup('<cookie-name>')`, the real call may
    have been `self.session.get(URL)` followed by `BeautifulSoup(response.text,
    ...)`; the cookie-name literal was hoisted into the wrong call position.

    This is evidence-only: the cookie literal must also appear in a cookie-set
    call in the emitted text, and the URL must come from the recovered constants
    pool. There is intentionally no application-specific fallback URL.
    """
    if not text:
        return text
    import ast as _ast
    import re as _re
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    bs_literals = []
    for node in _ast.walk(tree):
        if (isinstance(node, _ast.Call)
                and isinstance(node.func, _ast.Name)
                and node.func.id == 'BeautifulSoup'
                and node.args
                and isinstance(node.args[0], _ast.Constant)
                and isinstance(node.args[0].value, str)):
            lit = node.args[0].value
            if _re.fullmatch(r'[A-Za-z_][\w.-]{0,40}', lit):
                bs_literals.append(lit)
    if not bs_literals:
        return text

    try:
        flat_strings = extract_all_strings(list(consts or []))
    except Exception:
        flat_strings = [c for c in (consts or []) if isinstance(c, str)]
    const_string_set = set(flat_strings)
    cookie_context = bool(_re.search(r'\bcookies?\b', text, _re.IGNORECASE))
    parser_literals = {'html', 'html.parser', 'xml', 'lxml', 'html5lib'}
    cookie_literals = []
    for lit in bs_literals:
        if lit.lower() in parser_literals:
            continue
        lit_re = _re.escape(lit)
        if _re.search(r"\.cookies\.set\s*\(\s*(['\"])" + lit_re + r"\1", text):
            cookie_literals.append(lit)
        elif cookie_context and lit in const_string_set:
            cookie_literals.append(lit)
    if not cookie_literals:
        return text

    urls = []
    seen_urls = set()
    for c in flat_strings:
        if isinstance(c, str) and c.startswith(('http://', 'https://')):
            if c not in seen_urls:
                seen_urls.add(c)
                urls.append(c)
    if not urls:
        return text

    def _score_url(u):
        # Universal URL ranking: prefer URLs already present in recovered text
        # and generic human-facing path segments; never boost product-specific
        # path tokens from any one application family.
        low = u.lower()
        score = 0
        for needle in ('login', 'auth', 'account', 'profile', 'dashboard',
                       'home', 'index', 'user', 'page'):
            if needle in low:
                score += 3
        for needle in ('check', 'ping', 'api', 'ajax', 'data', 'json',
                       'validate', 'remove', 'insert', 'delete'):
            if needle in low:
                score -= 4
        if u in text:
            score += 2
        if len(urls) == 1:
            score += 1
        return score

    url = max(urls, key=_score_url)
    if _score_url(url) <= 0:
        return text

    for lit in set(cookie_literals):
        text = text.replace("BeautifulSoup(%r)" % lit, "self.session.get(%r)" % url)
        text = text.replace('BeautifulSoup("%s")' % lit, "self.session.get(%r)" % url)

    return text


def _ndl_heal_misattributed_statements_v53(text):
    """Compatibility wrapper: avoid product-specific statement removal."""
    return text

def _ndl_heal_if_polarity_evidence_v49(text, consts=None):
    """V49: Fix if-polarity using token group evidence.

    When `if X:` is followed by normal code but the consts pool has
    warning strings at a line number BETWEEN the if-condition and the
    if-body, the polarity is inverted. The warning should be in the
    if-body (guard), not after it.

    Pattern (WRONG):
        if current_item:
            account_id = current_item.data(...)
        for account in self.resource_manager.accounts:
            ...

    Should be (CORRECT):
        if not current_item:
            QtWidgets.QMessageBox.warning(...)
            return
        account_id = current_item.data(...)
        for account in self.resource_manager.accounts:
            ...

    Detection: the if-body has NORMAL code (assignment/method call without
    warning/return), but the consts pool has warning strings that would
    fit a guard pattern.
    """
    if not text or not consts:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    # Check if consts has warning-style strings
    _has_warning_consts = any(
        isinstance(c, str) and ('Please' in c or 'No ' in c or 'Missing' in c)
        for c in consts)
    if not _has_warning_consts:
        return text

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def _heal_body(self, body):
            new_body = []
            for i, stmt in enumerate(body):
                if isinstance(stmt, _ast.If):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    # V49: Check if this is an inverted guard
                    # Signal: the if-body has NORMAL code (assignment/data call)
                    # but NO warning/return — the guard is missing
                    _has_warning = any(self._has_warning_call(s) for s in stmt.body)
                    _has_return = any(isinstance(s, _ast.Return) for s in stmt.body)
                    _has_assignment = any(isinstance(s, _ast.Assign) for s in stmt.body)
                    _has_data_call = any(self._has_data_call(s) for s in stmt.body)
                    _is_simple_cond = isinstance(stmt.test, (_ast.Name, _ast.Attribute))
                    _no_else = not stmt.orelse
                    # Next statement after the if is a for-loop or more normal code
                    _next_is_normal = (i + 1 < len(body) and
                                       not isinstance(body[i+1], (_ast.Return, _ast.Raise)))

                    # V49: If the if-body has normal code (assignment/data_call)
                    # but NO warning/return, and there's no else, and the next
                    # statement is normal — the polarity is likely inverted.
                    # The guard body was dropped by the CFG recovery.
                    if (_is_simple_cond and _no_else and _next_is_normal
                            and (_has_assignment or _has_data_call)
                            and not _has_warning and not _has_return):
                        # Invert: `if X:` -> `if not X:`
                        stmt.test = _ast.UnaryOp(op=_ast.Not(), operand=stmt.test)
                        # Add a pass to the if-body (the real guard was dropped)
                        # The warning_return healer will fill it in later
                        _ast.fix_missing_locations(stmt)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._heal_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._heal_body(h.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    stmt.finalbody = self._heal_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._heal_body(stmt.body)
                new_body.append(stmt)
            return new_body

        def _has_warning_call(self, stmt):
            for sub in _ast.walk(stmt):
                if (isinstance(sub, _ast.Call) and isinstance(sub.func, _ast.Attribute)
                        and sub.func.attr in ('warning', 'critical', 'information')):
                    return True
            return False

        def _has_data_call(self, stmt):
            for sub in _ast.walk(stmt):
                if (isinstance(sub, _ast.Call) and isinstance(sub.func, _ast.Attribute)
                        and sub.func.attr == 'data'):
                    return True
            return False

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_render_tuple_unpack_v49(tokens, vn=None, consts=None, method_set=None):
    """V49: render tuple unpack calls without product-specific method maps."""
    if not tokens or not vn:
        return None
    toks = [t for t in tokens if t]
    if not toks:
        return None

    def _ident(t):
        return bool(re.fullmatch(r'[A-Za-z_]\w*', str(t)))

    def _looks_self_attr(t):
        low = str(t).lower()
        return (_ident(t) and (low in {'signals', 'session', 'headers', 'centralwidget'}
                or any(low.endswith(s) for s in ('_manager', '_service', '_client',
                                                 '_parser', '_validator', '_provider',
                                                 '_store', '_cache', '_adapter'))))

    allowed = set(method_set or [])
    const_names = {c for c in (consts or []) if isinstance(c, str)}
    verb_re = re.compile(r'^(get|parse|read|load|fetch|check|validate|verify|resolve|split|extract)_?')
    method_name = None
    method_idx = None
    for i, t in enumerate(toks):
        if not _ident(t) or t in {'self', 'cls', 'Qt', 'QtWidgets', 'QtCore'}:
            continue
        if t in allowed or (t in const_names and verb_re.match(t)) or (allowed and t in allowed):
            method_name = t
            method_idx = i
            break
    if method_name is None:
        return None

    locals_list = []
    seen_self = False
    for v in vn:
        if v == 'self' and not seen_self:
            seen_self = True
            continue
        if seen_self and v != 'self':
            locals_list.append(v)
    if len(locals_list) < 2:
        return None

    local_set = set(locals_list)
    args = [t for t in toks[method_idx + 1:] if t in local_set]
    start = 0
    for i, v in enumerate(locals_list):
        if v in args or v in toks[:method_idx]:
            start = i + 1
    skip = {'i', 'j', 'k', 'idx', 'index', 'item', 'entry', 'elem', 'node', 'row'}
    targets = [v for v in locals_list[start:] if v not in skip and v not in args and v not in toks]
    if len(targets) < 2:
        targets = [v for v in locals_list if v not in skip and v not in args and v not in toks]
    if len(targets) < 2:
        return None

    receiver = 'self'
    if method_idx and method_idx > 0:
        prefix = [t for t in toks[:method_idx] if _ident(t)]
        if prefix:
            receiver = '.'.join(prefix)
            if _looks_self_attr(prefix[0]):
                receiver = 'self.' + receiver
    call_args = ', '.join(args)
    lhs = ', '.join(targets[:3])
    return f'{lhs} = {receiver}.{method_name}({call_args})' if call_args else f'{lhs} = {receiver}.{method_name}()'

def _ndl_render_if_else_fstring_v49(tokens, vn=None, consts=None, method_set=None):
    """V49: split success/error f-string calls using receiver tokens only."""
    if not tokens:
        return None
    toks = [t for t in tokens if t]
    has_success = any('[SUCCESS]' in t for t in toks)
    has_error = any('[ERROR]' in t for t in toks)
    if not (has_success and has_error):
        return None
    error_idx = next((i for i, t in enumerate(toks) if '[ERROR]' in t), None)
    if error_idx is None:
        return None

    def _ident(t):
        return bool(re.fullmatch(r'[A-Za-z_]\w*', str(t)))

    def _looks_self_attr(t):
        low = str(t).lower()
        return (_ident(t) and (low in {'signals', 'session', 'headers', 'centralwidget'}
                or any(low.endswith(s) for s in ('_edit', '_label', '_view', '_widget',
                                                 '_logger', '_log', '_output', '_panel'))
                or any(low.startswith(p) for p in ('label_', 'plaintext', 'textedit'))))

    infer_set = (method_set or set()) | globals().get('_V40_QT_METHODS', set()) | {'append', 'write', 'emit', 'setText', 'appendPlainText'}

    def _render(part):
        method = None
        method_idx = None
        for i, t in enumerate(part):
            if _ident(t) and t in infer_set:
                method = t
                method_idx = i
                break
        if method is None:
            return None
        receiver = 'self'
        if method_idx > 0:
            prefix = [t for t in part[:method_idx] if _ident(t)]
            if prefix:
                receiver = '.'.join(prefix)
                if _looks_self_attr(prefix[0]):
                    receiver = 'self.' + receiver
        fstring_toks = [t for t in part[method_idx + 1:]
                        if (len(t) >= 2 and t[0] in ("'", '"') and t[-1] == t[0])
                        or _ident(t)]
        fstr = _ndl_render_fstring_v42(fstring_toks) if fstring_toks else None
        return f'{receiver}.{method}({fstr})' if fstr else None

    success_call = _render(toks[:error_idx])
    error_call = _render(toks[error_idx:])
    if not (success_call and error_call):
        return None
    cond_var = next((v for v in (vn or []) if v in {'ok', 'success', 'valid', 'is_valid', 'result'} or str(v).startswith('is_')), None) or 'ok'
    return [f'if {cond_var}:', f'    {success_call}', 'else:', f'    {error_call}']

def _ndl_heal_if_polarity_v48(text):
    """V48: Fix if-polarity inversion.

    Nuitka compiles `if not X:` as `if X: goto else_block`. The CFG
    recovery sees the positive branch and emits `if X:` instead of
    `if not X:`. This healer detects early-exit guard patterns and
    inverts the polarity.

    Pattern:
        if current_item:          ->    if not current_item:
            account_id = ...                QtWidgets.QMessageBox.warning(...)
                                          return
    The key signal: the if-body contains a warning call or return, and
    the else-block (or fall-through) contains the "normal" logic.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def _heal_body(self, body):
            new_body = []
            for i, stmt in enumerate(body):
                if isinstance(stmt, _ast.If):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    # Check if this is an inverted guard:
                    # - The if-body has a warning/return/setEnabled pattern
                    # - OR the if-body is just `pass` and the else has real logic
                    _has_warning = any(self._has_warning_call(s) for s in stmt.body)
                    _has_return = any(isinstance(s, _ast.Return) for s in stmt.body)
                    _has_pass_only = (len(stmt.body) == 1 and isinstance(stmt.body[0], _ast.Pass))
                    _has_void_call = self._has_void_receiver_call(stmt.body)
                    _else_has_real = bool(stmt.orelse) and any(
                        not isinstance(s, _ast.Pass) for s in stmt.orelse)
                    # Next statement after the if is "normal" logic
                    _next_is_normal = (i + 1 < len(body) and
                                       not isinstance(body[i+1], (_ast.Return, _ast.Raise)))

                    # V48.2: Only invert SIMPLE conditions (Name/Attribute),
                    # NOT comparison conditions (X == Y, X != Y, etc.)
                    _is_simple_cond = isinstance(stmt.test, (_ast.Name, _ast.Attribute))
                    if _is_simple_cond and (_has_warning or _has_return or _has_void_call or
                            (_has_pass_only and _next_is_normal)):
                        # Invert the polarity
                        if isinstance(stmt.test, _ast.UnaryOp) and isinstance(stmt.test.op, _ast.Not):
                            # Already `if not X:` — don't double-invert
                            pass
                        else:
                            # Invert: `if X:` -> `if not X:`
                            stmt.test = _ast.UnaryOp(
                                op=_ast.Not(),
                                operand=stmt.test)
                            _ast.fix_missing_locations(stmt)
                            # If the if-body is just pass, add a return
                            # (early-exit guards typically return)
                            if _has_pass_only and not _has_return:
                                stmt.body = [_ast.Return(value=None)]
                                _ast.fix_missing_locations(stmt)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._heal_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._heal_body(h.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    stmt.finalbody = self._heal_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._heal_body(stmt.body)
                new_body.append(stmt)
            return new_body

        def _has_warning_call(self, stmt):
            for sub in _ast.walk(stmt):
                if (isinstance(sub, _ast.Call) and isinstance(sub.func, _ast.Attribute)
                        and sub.func.attr in ('warning', 'critical', 'information')):
                    return True
            return False

        def _has_void_receiver_call(self, body):
            """Check if body has self.centralwidget.window() void call."""
            for s in body:
                if (isinstance(s, _ast.Expr) and isinstance(s.value, _ast.Call)):
                    call = s.value
                    if (isinstance(call.func, _ast.Attribute)
                            and isinstance(call.func.value, _ast.Attribute)
                            and isinstance(call.func.value.value, _ast.Name)
                            and call.func.value.value.id == 'self'
                            and call.func.value.attr == 'centralwidget'
                            and call.func.attr == 'window'
                            and not call.args):
                        return True
            return False

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_while_true_cond_hoist_v90(text):
    """Hoist `while True:` + sole positive `if <cond>:` -> `while <cond>:`.

    Nuitka lowers `while X: <body>` as a loop that re-tests X at the header;
    the structured emitter renders this as `while True:` whose SOLE body
    statement is `if X: <body>` (no else). Convert that exact shape back to
    `while X: <body>` so the output matches the original `while`-form (the
    `while True: if X:` wrapper is the Phase-6 loop-condition-hoist frontier
    noted separately from body-fill).

    TEXT-LEVEL (not ast.unparse): only the `while True:` header and the
    if-body dedent change — every other line is byte-identical, so the
    transform is isolated from whole-module reformatting noise. GATED to the
    unambiguous Nuitka lowering shape: the while-body must be a SINGLE `if`
    with NO `else` and NOTHING else at the if's indent inside the while. A
    real `while True:` with extra statements or an else branch is left
    untouched (hoisting it would change semantics)."""
    if not text:
        return text
    import re as _re

    def _ilen(s):
        return len(s) - len(s.lstrip())

    lines = text.split('\n')
    out = []
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i]
        mw = _re.match(r'^(\s*)while True:\s*$', line)
        if mw:
            wlen = len(mw.group(1))
            j = i + 1
            while j < n and lines[j].strip() == '':
                j += 1
            if j < n:
                mif = _re.match(r'^(\s*)if (.+):\s*$', lines[j])
                if mif and len(mif.group(1)) > wlen:
                    iflen = len(mif.group(1))
                    cond = mif.group(2).strip()
                    unit = iflen - wlen
                    bs = j + 1
                    be = bs
                    has_body = False
                    while be < n:
                        bl = lines[be]
                        if bl.strip() == '':
                            be += 1
                            continue
                        if _ilen(bl) > iflen:
                            has_body = True
                            be += 1
                        else:
                            break
                    else_found = False
                    extra = False
                    k = be
                    while k < n:
                        bl = lines[k]
                        if bl.strip() == '':
                            k += 1
                            continue
                        il = _ilen(bl)
                        if il <= wlen:
                            break
                        if il == iflen:
                            if _re.match(r'^\s*else\s*:\s*$', bl):
                                else_found = True
                            else:
                                extra = True
                        break
                    if has_body and not else_found and not extra:
                        out.append(' ' * wlen + 'while ' + cond + ':')
                        for b in range(bs, be):
                            bl = lines[b]
                            if bl.strip() == '':
                                out.append('')
                            elif bl.startswith(' ' * unit):
                                out.append(bl[unit:])
                            else:
                                out.append(bl.lstrip())
                        i = be
                        continue
        out.append(line)
        i += 1
    return '\n'.join(out)


def _ndl_heal_while_true_artifact_v43(text):
    """V43: Remove `while True:` wrappers that are CFG recovery artifacts.

    When the original source had a simple if/else pattern but the CFG
    recovery wrapped it in a `while True:` loop (because the CFG saw
    a back-edge that was actually an exception handler), unwrap it.

    Pattern:
        while True:
            <stmt1>
            <stmt2>
            ...
    becomes:
        <stmt1>
        <stmt2>
        ...

    Only fires when:
    - The while body has no `break` (so it's not a real loop)
    - The while condition is the constant `True`
    - The body has at least 2 statements
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def _try_unwrap(self, body):
            new_body = []
            for stmt in body:
                if isinstance(stmt, _ast.While):
                    # Check if it's `while True:` with no break
                    is_true = (isinstance(stmt.test, _ast.Constant)
                               and stmt.test.value is True)
                    has_break = any(isinstance(s, _ast.Break) for s in _ast.walk(stmt))
                    if is_true and not has_break and len(stmt.body) >= 2:
                        # Completeness (Nuitka 4.x): real monitor/event loops are
                        # `while True:` without `break` (they `return` / `continue`
                        # / sleep). Unwrapping those flattens get_timer-style
                        # bodies into straight-line sibling calls. Only unwrap
                        # trivial straight-line exception-handler back-edge
                        # artifacts (no nested control flow, no real calls).
                        has_nested = any(
                            isinstance(s, (_ast.If, _ast.For, _ast.While,
                                           _ast.Try, _ast.With,
                                           _ast.AsyncFor, _ast.AsyncWith))
                            for s in stmt.body)
                        has_call = any(
                            isinstance(n, _ast.Call)
                            for s in stmt.body for n in _ast.walk(s))
                        if has_nested or has_call:
                            new_body.append(stmt)
                            continue
                        # Unwrap: replace the while with its body
                        # Recurse into the body first
                        stmt.body = self._try_unwrap(stmt.body)
                        new_body.extend(stmt.body)
                        continue
                # Recurse
                if isinstance(stmt, _ast.If):
                    stmt.body = self._try_unwrap(stmt.body)
                    stmt.orelse = self._try_unwrap(stmt.orelse)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._try_unwrap(stmt.body)
                    stmt.orelse = self._try_unwrap(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._try_unwrap(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._try_unwrap(h.body)
                    stmt.orelse = self._try_unwrap(stmt.orelse)
                    stmt.finalbody = self._try_unwrap(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._try_unwrap(stmt.body)
                new_body.append(stmt)
            return new_body

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._try_unwrap(node.body)
            if not node.body:
                node.body = [_ast.Pass()]
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_reattach_label_settext_v43(text, consts=None):
    """Compatibility wrapper: do not synthesize label text updates."""
    return text

def _ndl_heal_context_exit_json_dump_v83(text):
    """Universal: Nuitka with-open epilogue can mis-bind ``json.dump`` as
    ``self.__exit__.dump`` / ``<temp>.__exit__.dump`` when the context-
    manager exit helper is left in the receiver register. Rewrite to
    ``json.dump`` only when the call shape is dump(obj, file, indent=...)
    (the standard stdlib signature) and ``json`` is already imported or
    referenced in the module. Never invents imports; inert otherwise.
    """
    if not text or '__exit__.dump' not in text:
        return text
    if not re.search(r'(?m)^\s*(?:import\s+json\b|from\s+json\s+import\b)', text):
        if 'json' not in text:
            return text
    # self.__exit__.dump(x, f, indent=4)  /  v0.__exit__.dump(...)
    fixed = re.sub(
        r'(?<![\w.])(?:self|[A-Za-z_]\w*)\.__exit__\.dump\s*\(',
        'json.dump(',
        text,
    )
    if fixed == text:
        return text
    try:
        import ast as _ast
        _ast.parse(fixed)
        return fixed
    except Exception:
        return text


def _ndl_heal_phantom_if_pass_v41(text):
    """V41: Remove `if X: pass` blocks that are CFG recovery artifacts.

    The CFG walk sometimes produces phantom conditions like:
        if account.id:
            pass
        if account.id:
            pass
    These are degenerate if-blocks with no real body — remove them
    entirely. Only removes blocks where the body is EXACTLY `pass`
    (no other statements).

    V92: only drop when the condition is a pure recovery placeholder
    (`_cond` / `self._attr` / `self is None`…).  An evidence-backed
    `if self.login: pass` / `if self.spinBox.value >= …: pass` is a
    real guard whose body failed upstream — keep it so later passes
    (or the human) still see the recovered predicate.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def _filter_body(self, body):
            out = []
            for stmt in body:
                # Recurse into nested blocks
                if isinstance(stmt, _ast.If):
                    stmt.body = self._filter_body(stmt.body)
                    stmt.orelse = self._filter_body(stmt.orelse)
                    # Remove if body is just pass AND orelse is empty AND
                    # the test is a placeholder — never delete real predicates.
                    if (len(stmt.body) == 1 and isinstance(stmt.body[0], _ast.Pass)
                            and not stmt.orelse
                            and _ndl_is_placeholder_test(stmt.test)):
                        continue  # drop this phantom if
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._filter_body(stmt.body)
                    stmt.orelse = self._filter_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._filter_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._filter_body(h.body)
                    stmt.orelse = self._filter_body(stmt.orelse)
                    stmt.finalbody = self._filter_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._filter_body(stmt.body)
                out.append(stmt)
            return out

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._filter_body(node.body)
            if not node.body:
                node.body = [_ast.Pass()]
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

        def visit_Module(self, node):
            self.generic_visit(node)
            return node

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_missing_messagebox_v41(text, consts=None):
    """Compatibility wrapper: do not synthesize message-box calls."""
    return text

def _ndl_heal_reattach_self_calls_v41(text, consts=None, method_set=None):
    """V41: When a function body has `if <cond>:` with a body containing
    only `self.centralwidget.window()` (a degenerate call that lost its
    arguments), replace it with the standard QMessageBox.warning pattern.

    This is a targeted healer for the common pattern:
        if not <cond>:
            QtWidgets.QMessageBox.warning(self.centralwidget.window(), 'Title', 'Message')
            return

    The CFG walk drops the QMessageBox.warning call and the return,
    leaving only `self.centralwidget.window()` (the receiver expression).
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    # Collect warning/message strings from consts
    _warning_strings = []
    if consts:
        for c in consts:
            if (isinstance(c, str) and len(c) > 5 and len(c) < 200
                    and not c.startswith(('http', '__', '/', '<', '%'))
                    and ' ' in c):
                _warning_strings.append(c)

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._heal_body(node.body)
            return node

        def _heal_body(self, body):
            new_body = []
            for i, stmt in enumerate(body):
                # Recurse
                if isinstance(stmt, _ast.If):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    # Check if this is a degenerate if with self.centralwidget.window()
                    # as the only body statement
                    if (len(stmt.body) == 1
                            and isinstance(stmt.body[0], _ast.Expr)
                            and isinstance(stmt.body[0].value, _ast.Call)):
                        call = stmt.body[0].value
                        # Check if it's self.centralwidget.window()
                        if (isinstance(call.func, _ast.Attribute)
                                and isinstance(call.func.value, _ast.Attribute)
                                and isinstance(call.func.value.value, _ast.Name)
                                and call.func.value.value.id == 'self'
                                and call.func.value.attr == 'centralwidget'
                                and call.func.attr == 'window'
                                and not call.args):
                            # This is a degenerate call — the real body was
                            # QtWidgets.QMessageBox.warning(self.centralwidget.window(), ...)
                            # We can't recover the exact arguments, but we can
                            # at least add a return statement after it.
                            stmt.body.append(_ast.Return(value=None))
                            _ast.fix_missing_locations(stmt)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._heal_body(stmt.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._heal_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._heal_body(h.body)
                    stmt.orelse = self._heal_body(stmt.orelse)
                    stmt.finalbody = self._heal_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._heal_body(stmt.body)
                new_body.append(stmt)
            return new_body

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_missing_label_settext_v41(text, consts=None):
    """Compatibility wrapper: do not synthesize missing label updates."""
    return text

def _ndl_heal_drop_void_receiver_calls_v41(text):
    """V41: Remove `self.centralwidget.window()` void calls that are
    artifacts of dropped QMessageBox.warning calls.

    When the CFG walk drops `QtWidgets.QMessageBox.warning(self.centralwidget.window(), ...)`,
    it leaves behind `self.centralwidget.window()` as a void call.
    Remove these — they're not real statements.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def _filter_body(self, body):
            out = []
            for stmt in body:
                # Check if this is a void self.centralwidget.window() call
                if (isinstance(stmt, _ast.Expr) and isinstance(stmt.value, _ast.Call)):
                    call = stmt.value
                    if (isinstance(call.func, _ast.Attribute)
                            and isinstance(call.func.value, _ast.Attribute)
                            and isinstance(call.func.value.value, _ast.Name)
                            and call.func.value.value.id == 'self'
                            and call.func.value.attr == 'centralwidget'
                            and call.func.attr == 'window'
                            and not call.args):
                        continue  # drop this void call
                # Recurse
                if isinstance(stmt, _ast.If):
                    stmt.body = self._filter_body(stmt.body)
                    stmt.orelse = self._filter_body(stmt.orelse)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._filter_body(stmt.body)
                    stmt.orelse = self._filter_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._filter_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._filter_body(h.body)
                    stmt.orelse = self._filter_body(stmt.orelse)
                    stmt.finalbody = self._filter_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._filter_body(stmt.body)
                out.append(stmt)
            return out

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._filter_body(node.body)
            if not node.body:
                node.body = [_ast.Pass()]
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

        def visit_Module(self, node):
            self.generic_visit(node)
            return node

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text

def _ndl_heal_orphan_break_continue_v36(text):
    """V36: Remove `break`/`continue` statements that appear outside any loop.

    The per-statement walk recovers `break`/`continue` from the native
    code but loses the enclosing loop structure, producing orphan
    `break`/`continue` statements at function-body level (SyntaxError
    when actually compiled). This healer walks the AST and drops any
    `break`/`continue` that is not inside a `for`/`while` loop.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    class _S(_ast.NodeTransformer):
        def __init__(self):
            self._loop_depth = 0

        def _filter_body(self, body):
            out = []
            for stmt in body:
                if isinstance(stmt, (_ast.Break, _ast.Continue)) and self._loop_depth == 0:
                    continue  # drop orphan break/continue
                out.append(stmt)
            return out

        def visit_For(self, node):
            self.generic_visit(node)
            self._loop_depth += 1
            node.body = self._filter_body(node.body)
            node.orelse = self._filter_body(node.orelse)
            self._loop_depth -= 1
            return node

        def visit_While(self, node):
            self.generic_visit(node)
            self._loop_depth += 1
            node.body = self._filter_body(node.body)
            node.orelse = self._filter_body(node.orelse)
            self._loop_depth -= 1
            return node

        def visit_FunctionDef(self, node):
            old = self._loop_depth
            self._loop_depth = 0
            self.generic_visit(node)
            node.body = self._filter_body(node.body)
            self._loop_depth = old
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

        def visit_Module(self, node):
            old = self._loop_depth
            self._loop_depth = 0
            self.generic_visit(node)
            node.body = self._filter_body(node.body)
            self._loop_depth = old
            return node

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_unreachable_after_return_v36(text):
    """V36: Drop statements after a `return`/`break`/`continue`/`raise`
    in the same block. Dead code from CFG recovery that confuses readers
    and can introduce undefined-name references."""
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    _TERMINATORS = (_ast.Return, _ast.Break, _ast.Continue, _ast.Raise)

    def _trim_body(body):
        out = []
        for stmt in body:
            out.append(stmt)
            if isinstance(stmt, _TERMINATORS):
                break
        return out

    class _S(_ast.NodeTransformer):
        def _walk_body(self, body):
            # Recurse into nested blocks first.
            new_body = []
            for stmt in body:
                # Recurse into compound statements.
                if isinstance(stmt, _ast.If):
                    stmt.body = self._walk_body(stmt.body)
                    stmt.orelse = self._walk_body(stmt.orelse)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._walk_body(stmt.body)
                    stmt.orelse = self._walk_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._walk_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._walk_body(h.body)
                    stmt.orelse = self._walk_body(stmt.orelse)
                    stmt.finalbody = self._walk_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._walk_body(stmt.body)
                new_body.append(stmt)
            return _trim_body(new_body)

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._walk_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._walk_body(node.body)
            return node

        def visit_Module(self, node):
            self.generic_visit(node)
            # Don't trim at module level (no return semantics).
            return node

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_redundant_double_login_v36(text):
    """V36: Collapse `self.login()` followed by `if self.login():` into
    a single `if not self.login(): return` form.

    The per-statement walk recovers BOTH the void `self.login()` call AND
    the subsequent `if self.login():` test from the same source line
    `if not self.login(): return` — producing a duplicated call. This
    healer detects the pattern and collapses it.

    Pattern:
        self.login()
        if self.login():
            ...
    becomes:
        if not self.login():
            return
    (when the if-body is empty or just `pass`)

    Or more conservatively:
        if self.login():
            ...
    (when the if-body has real content, just drop the void call before)
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    def _is_self_call(stmt, method_name):
        return (isinstance(stmt, _ast.Expr)
                and isinstance(stmt.value, _ast.Call)
                and isinstance(stmt.value.func, _ast.Attribute)
                and isinstance(stmt.value.func.value, _ast.Name)
                and stmt.value.func.value.id == 'self'
                and stmt.value.func.attr == method_name
                and not stmt.value.args
                and not stmt.value.keywords)

    def _is_if_self_call(stmt, method_name):
        if not isinstance(stmt, _ast.If):
            return False
        test = stmt.test
        # `if self.X():` (positive) or `if not self.X():` (negated)
        if isinstance(test, _ast.Call):
            return (isinstance(test.func, _ast.Attribute)
                    and isinstance(test.func.value, _ast.Name)
                    and test.func.value.id == 'self'
                    and test.func.attr == method_name
                    and not test.args and not test.keywords)
        if isinstance(test, _ast.UnaryOp) and isinstance(test.op, _ast.Not):
            inner = test.operand
            return (isinstance(inner, _ast.Call)
                    and isinstance(inner.func, _ast.Attribute)
                    and isinstance(inner.func.value, _ast.Name)
                    and inner.func.value.id == 'self'
                    and inner.func.attr == method_name
                    and not inner.args and not inner.keywords)
        return False

    class _S(_ast.NodeTransformer):
        def _walk_body(self, body):
            new_body = []
            i = 0
            while i < len(body):
                stmt = body[i]
                # Recurse into nested blocks first.
                if isinstance(stmt, _ast.If):
                    stmt.body = self._walk_body(stmt.body)
                    stmt.orelse = self._walk_body(stmt.orelse)
                elif isinstance(stmt, (_ast.For, _ast.While)):
                    stmt.body = self._walk_body(stmt.body)
                    stmt.orelse = self._walk_body(stmt.orelse)
                elif isinstance(stmt, _ast.Try):
                    stmt.body = self._walk_body(stmt.body)
                    for h in stmt.handlers:
                        h.body = self._walk_body(h.body)
                    stmt.orelse = self._walk_body(stmt.orelse)
                    stmt.finalbody = self._walk_body(stmt.finalbody)
                elif isinstance(stmt, _ast.With):
                    stmt.body = self._walk_body(stmt.body)
                # Detect: <self.X()> followed by <if self.X():> or <if not self.X():>
                if (i + 1 < len(body)
                        and isinstance(stmt, _ast.Expr)
                        and isinstance(stmt.value, _ast.Call)
                        and isinstance(stmt.value.func, _ast.Attribute)):
                    method = stmt.value.func.attr
                    if _is_self_call(stmt, method) and i + 1 < len(body):
                        nxt = body[i + 1]
                        if _is_if_self_call(nxt, method):
                            # Drop the void call, keep the if.
                            new_body.append(nxt)
                            i += 2
                            continue
                new_body.append(stmt)
                i += 1
            return new_body

        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._walk_body(node.body)
            return node

        def visit_AsyncFunctionDef(self, node):
            self.generic_visit(node)
            node.body = self._walk_body(node.body)
            return node

        def visit_Module(self, node):
            self.generic_visit(node)
            node.body = self._walk_body(node.body)
            return node

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_body_has_early_return_guard(body):
    """True when *body* opens with ``if not <expr>: return`` (early-exit)."""
    if not body:
        return False
    import ast as _ast
    try:
        tree = _ast.parse(
            "def _g():\n" + "\n".join(
                ("    " + l) if l.strip() else l for l in body))
    except Exception:
        return False
    stmts = tree.body[0].body
    if not stmts or not isinstance(stmts[0], _ast.If):
        return False
    node = stmts[0]
    if not (isinstance(node.test, _ast.UnaryOp)
            and isinstance(node.test.op, _ast.Not)):
        return False
    return (len(node.body) == 1 and isinstance(node.body[0], _ast.Return)
            and not node.orelse)


def _ndl_heal_leading_void_truth_guard_v92(text):
    """V92: Restore a lost early-return guard from a leading void truth-call.

    When the CFG void-emits a truth-tested ``self.m()`` and drops
    ``if not self.m(): return``, the body collapses to::

        self.m()
        self.rest()

    Inverse of the V36 duplicate-void+if collapse.  Only fires when:
      * first stmt is zero-arg ``self.<m>()``
      * ``<m>`` looks predicate-like (``login``/``is_``/``check``/…)
      * at least one more real stmt follows
      * that next stmt is NOT ``if self.<m>:`` / ``if self.<m>():``
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    _PRED = re.compile(
        r'^(?:is_|has_|can_|should_|login|authenticate|connect|'
        r'validate|check|verify|ok|success|running|enabled)',
        re.I)

    def _is_void_self_pred(stmt):
        if not (isinstance(stmt, _ast.Expr)
                and isinstance(stmt.value, _ast.Call)):
            return None
        call = stmt.value
        if call.args or call.keywords:
            return None
        fn = call.func
        if not (isinstance(fn, _ast.Attribute)
                and isinstance(fn.value, _ast.Name)
                and fn.value.id == 'self'
                and _PRED.match(fn.attr)):
            return None
        return fn.attr

    def _is_if_self_pred(stmt, method):
        if not isinstance(stmt, _ast.If):
            return False
        test = stmt.test
        if isinstance(test, _ast.UnaryOp) and isinstance(test.op, _ast.Not):
            test = test.operand
        if isinstance(test, _ast.Call):
            fn = test.func
            return (isinstance(fn, _ast.Attribute)
                    and isinstance(fn.value, _ast.Name)
                    and fn.value.id == 'self'
                    and fn.attr == method
                    and not test.args and not test.keywords)
        if isinstance(test, _ast.Attribute):
            return (isinstance(test.value, _ast.Name)
                    and test.value.id == 'self'
                    and test.attr == method)
        return False

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            self.generic_visit(node)
            body = list(node.body)
            # Skip docstring
            i0 = 0
            if (body and isinstance(body[0], _ast.Expr)
                    and isinstance(body[0].value, _ast.Constant)
                    and isinstance(body[0].value.value, str)):
                i0 = 1
            if i0 >= len(body):
                return node
            method = _is_void_self_pred(body[i0])
            if method is None:
                return node
            rest = body[i0 + 1:]
            if not rest:
                return node
            if _is_if_self_pred(rest[0], method):
                return node  # V36 owns this shape
            # Need at least one non-pass real follower
            if all(isinstance(s, _ast.Pass) for s in rest):
                return node
            guard = _ast.If(
                test=_ast.UnaryOp(
                    op=_ast.Not(),
                    operand=_ast.Call(
                        func=_ast.Attribute(
                            value=_ast.Name(id='self', ctx=_ast.Load()),
                            attr=method, ctx=_ast.Load()),
                        args=[], keywords=[])),
                body=[_ast.Return(value=None)],
                orelse=[])
            node.body = body[:i0] + [guard] + rest
            _ast.fix_missing_locations(node)
            return node

        def visit_AsyncFunctionDef(self, node):
            return self.visit_FunctionDef(node)

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


# ── V93: universal KW_SPLIT kwnames-leak healer (text-level, AST-gated) ───────
# Nuitka's keyword-call helpers (CALL_FUNCTION_WITH_*_KW_SPLIT / *_VECTORCALL)
# pass a kwnames tuple of identifier strings alongside the positional values.
# When the register simulator cannot pair the keyword VALUES to the names, the
# kwnames tuple leaks into the emitted call as a bare trailing positional arg:
#     self.session.get(url, ('verify', 'timeout', 'headers'))
#     requests.get(url, ('params',))
#     params.text().split(('|',), ('params', 'headers', 'timeout'))
# A pure-identifier tuple is NEVER a real Python positional value, so this is
# always a decompiler artifact. The values are not textually recoverable here
# (provenance lives in the register sim, not the rendered text): mis-pairing the
# preceding positional as a kwarg value would FABRICATE wrong kwargs, which is
# worse than the honest drop. Therefore: DROP the leaked kwnames tuple, and also
# unwrap singleton non-identifier tuple args ('https://x',) -> 'https://x' (a
# scalar is never a 1-tuple at a Python call site). Pure-identifier singletons
# ('key',) are left alone (ambiguous with a 1-name kwnames). A kwnames tuple that
# is the SOLE call argument is left alone (may be a legitimate positional tuple
# such as dict.fromkeys(('a','b'))). String spans are masked before paren
# scanning; the whole file is AST-parse-gated so an unparseable result never
# ships. Universal across Nuitka versions / free & commercial; inert on calls
# that do not contain the leak shape.
_NDL_KW_IDENT = r"[A-Za-z_]\w*"
_NDL_KW_KWNAMES = re.compile(
    r"\(\s*'(?:%s)'\s*(?:,\s*'(?:%s)'\s*)+\)" % (_NDL_KW_IDENT, _NDL_KW_IDENT))
_NDL_KW_KWNAMES1 = re.compile(r"\(\s*'(%s)'\s*,\s*\)" % _NDL_KW_IDENT)
_NDL_KW_SING = re.compile(r"\(\s*'([^']+)'\s*,\s*\)")


def _ndl_kwnames_mask_strings(s):
    out = list(s)
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c in ("'", '"'):
            q3 = s[i:i + 3]
            if q3 in ("'''", '"""'):
                j = i + 3
                while j < n:
                    if s[j:j + 3] == q3:
                        break
                    if s[j] == "\\" and j + 1 < n:
                        out[j] = " "; out[j + 1] = " "; j += 2; continue
                    if s[j] != "\n":
                        out[j] = " "
                    j += 1
                i = j + 3
                continue
            j = i + 1
            while j < n:
                if s[j] == "\\" and j + 1 < n:
                    out[j] = " "; out[j + 1] = " "; j += 2; continue
                if s[j] == c:
                    break
                if s[j] != "\n":
                    out[j] = " "
                j += 1
            i = j + 1
            continue
        i += 1
    return "".join(out)


def _ndl_kwnames_enclosing_call(masked, tstart, tend):
    """Find the (open_idx, close_idx) of the call parenthesisation that contains
    the [tstart,tend) tuple span, scanning the string-MASKED text so string
    parens cannot confuse depth tracking. Returns None when the tuple's own '('
    IS the call paren (i.e. the match is the whole arg-list, not a sub-arg)."""
    depth = 0
    i = tstart - 1
    open_idx = None
    while i >= 0:
        c = masked[i]
        if c == ")":
            depth += 1
        elif c == "(":
            if depth == 0:
                open_idx = i
                break
            depth -= 1
        i -= 1
    if open_idx is None or open_idx >= tstart:
        return None
    depth = 0
    j = open_idx
    n = len(masked)
    while j < n:
        c = masked[j]
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                if j < tend:
                    return None
                return (open_idx, j)
        j += 1
    return None


def _ndl_kwnames_split_top(s):
    args = []
    depth = 0
    cur = []
    quote = None
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if quote:
            cur.append(ch)
            if ch == "\\" and i + 1 < n:
                cur.append(s[i + 1]); i += 2; continue
            if ch == quote:
                quote = None
            i += 1; continue
        if ch in ("'", '"'):
            quote = ch; cur.append(ch); i += 1; continue
        if ch in "([{":
            depth += 1; cur.append(ch); i += 1; continue
        if ch in ")]}":
            depth -= 1; cur.append(ch); i += 1; continue
        if ch == "," and depth == 0:
            args.append("".join(cur)); cur = []; i += 1; continue
        cur.append(ch); i += 1
    last = "".join(cur)
    if args or last.strip():
        args.append(last)
    return [a.strip() for a in args]


def _ndl_kwnames_transform_arglist(arglist):
    args = _ndl_kwnames_split_top(arglist)
    if not args:
        return arglist, False
    orig = list(args)
    # 1) drop a leaked kwnames tuple (not the sole arg).
    for ai, a in enumerate(args):
        tok = a.strip()
        if not (_NDL_KW_KWNAMES.fullmatch(tok) or _NDL_KW_KWNAMES1.fullmatch(tok)):
            continue
        if len(args) < 2:
            break  # sole-arg tuple: ambiguous (could be a legit positional tuple)
        del args[ai]
        break
    # 2) unwrap singleton non-identifier tuple args ('X',) -> 'X'.
    for ai, a in enumerate(args):
        m = _NDL_KW_SING.fullmatch(a.strip())
        if not m:
            continue
        inner = m.group(1)
        if re.fullmatch(_NDL_KW_IDENT, inner):
            continue
        args[ai] = "'" + inner + "'"
    if args == orig:
        return arglist, False
    return ", ".join(a for a in args if a), True


def _ndl_heal_kwnames_leak_v93(text):
    """V93: drop leaked KW_SPLIT kwnames tuples and unwrap singleton non-id tuple
    call args. Universal and AST-gated; see module note above."""
    if not text or "('" not in text:
        return text
    import ast as _ast_kw
    masked = _ndl_kwnames_mask_strings(text)
    targets = set()
    for rx in (_NDL_KW_KWNAMES, _NDL_KW_KWNAMES1, _NDL_KW_SING):
        for m in rx.finditer(text):
            enc = _ndl_kwnames_enclosing_call(masked, m.start(), m.end())
            if enc:
                targets.add(enc)
    if not targets:
        return text
    edits = []
    for oidx, cidx in targets:
        new_arglist, changed = _ndl_kwnames_transform_arglist(text[oidx + 1:cidx])
        if changed:
            edits.append((oidx + 1, cidx, new_arglist))
    if not edits:
        return text
    edits.sort(key=lambda e: e[0], reverse=True)
    out = text
    applied = []
    for st, en, rep in edits:
        if any(not (en <= a_st or st >= a_en) for a_st, a_en, _ in applied):
            continue
        out = out[:st] + rep + out[en:]
        applied.append((st, en, rep))
    try:
        _ast_kw.parse(out)
    except Exception:
        return text
    return out


def _ndl_split_top_mc_v93(s, sep=","):
    """Split ``s`` on ``sep`` at bracket/paren depth 0 (for trace tokens)."""
    out, depth, cur = [], 0, ""
    for ch in s:
        if ch in "([{":
            depth += 1; cur += ch
        elif ch in ")]}":
            depth -= 1; cur += ch
        elif ch == sep and depth == 0:
            out.append(cur); cur = ""
        else:
            cur += ch
    if cur.strip():
        out.append(cur)
    return out


def _ndl_synth_method_calls_strict_v93(trace_strings, self_attrs,
                                       nonself_methods=None,
                                       nonobject_attrs=None,
                                       def_names=None):
    """STRICT pattern-A synthesis: turn faithful-trace triples into
    ``self.receiver.method(args)`` statements.

    Only the UNAMBIGUOUS pattern is emitted: ``receiver, (args,), method``
    where the middle token is a literal arg-tuple.  The greedy 0-arg
    ``ident, ident`` pattern is INTENTIONALLY dropped: it fuses a receiver
    with the NEXT call's method and fabricates ``self.X.Y()`` noise.

    ``receiver`` is prefixed ``self.`` ONLY when it is a PROVEN self-attribute
    (already referenced as ``self.<receiver>`` in the emitted module).  A
    receiver that is a module/global/temp is skipped — never fabricate
    ``self.`` on an unproven name.  Each result is ast.parse-validated.

    ``nonself_methods`` (optional set) lists method names that already appear
    called on a NON-self receiver in the module (e.g. ``time.sleep``). A
    triple whose method is in this set is skipped: the faithful trace mis-binds
    module-function calls to the last-resolved self-attr, so synthesizing
    ``self.X.<module_func>(...)`` would fabricate wrong code.

    ``nonobject_attrs`` (optional set) lists self-attrs that are POSITIVELY
    assigned a non-Call value (``self.X = <Name|Constant|Attribute|...>`` —
    a str/int/name, NOT a constructed object). A triple whose receiver is in
    this set is skipped: calling ``.method(...)`` on a proven non-object
    (e.g. a string ``self.method``) is fabricated nonsense. This catches the
    false triple-association where the trace flattens tokens across statement
    boundaries (an ``if self.X in [a, b]:`` test + an unrelated ``func.X()``
    call get read as ``X, (a,b), func`` -> bogus ``self.X.func(a, b)``).
    Crucially this does NOT reject receivers whose construction the native
    walker DROPPED (``self.X`` referenced but never assigned in the emit) —
    those are exactly the lost widget constructions we want to recover.

    ``def_names`` (optional set) lists module/class method names (``def X``,
    ``async def X``). A triple whose receiver is in this set is skipped: a
    method name cannot also be a self instance-attribute holding an object, so
    ``self.<methodname>.<x>(...)`` is fabricated nonsense (the trace flattens a
    ``self.get_url()`` call plus an unrelated trailing token into bogus
    ``self.get_url.mode()``). Safe for real widget receivers — an instance attr
    is never a def name in the same class."""
    import ast as _ast_mc
    out = []
    for ts in (trace_strings or ()):
        if not isinstance(ts, str):
            continue
        toks = [t.strip() for t in _ndl_split_top_mc_v93(ts) if t.strip()]
        n = len(toks)
        i = 0
        while i < n:
            r = toks[i]
            if (i + 2 < n
                    and re.fullmatch(r"[A-Za-z_]\w*", r)
                    and toks[i + 1].startswith("(")
                    and toks[i + 1].rstrip().endswith(")")
                    and re.fullmatch(r"[A-Za-z_]\w*", toks[i + 2])):
                recv, argtup, meth = r, toks[i + 1], toks[i + 2]
                if nonself_methods and meth in nonself_methods:
                    i += 3
                    continue
                if nonobject_attrs and recv in nonobject_attrs:
                    i += 3
                    continue
                if def_names and recv in def_names:
                    i += 3
                    continue
                if recv in self_attrs:
                    args = [a.strip() for a in _ndl_split_top_mc_v93(
                        argtup[1:-1]) if a.strip()]
                    stmt = "self.%s.%s(%s)" % (recv, meth, ", ".join(args))
                    try:
                        _ast_mc.parse(stmt)
                        out.append(stmt)
                    except Exception:
                        pass
                i += 3
                continue
            i += 1   # lone ident / non-triple: skip (no 0-arg guessing)
    # de-duplicate preserving order
    _seen = set(); _res = []
    for s in out:
        if s not in _seen:
            _seen.add(s); _res.append(s)
    return _res


def _ndl_heal_method_calls_from_trace_v93(text, traces):
    """V93 universal: inject ``self.receiver.method(args)`` statements the
    native walker dropped (method-CALL statements are the lost class — see the
    stop_bot collapse), recovered from the faithful body trace.

    Additive and STRICTLY gated:
      * pattern-A triples only (``receiver, (literal args,), method``);
      * receiver MUST be a proven ``self.<receiver>`` attribute referenced
        somewhere in the emitted module (else it could be a module/global/temp
        and prefixing ``self.`` would fabricate a wrong statement);
      * each synthesized line is ast.parse-validated;
      * a statement already present in the method body (normalized) is not
        re-injected;
      * insertion preserves source formatting (line-based edit using AST
        end_lineno), placing new statements AFTER the last body statement, or
        BEFORE a trailing ``return``/``raise``/``pass`` terminator (a lone
        trailing ``pass`` is replaced);
      * the WHOLE module must still ast.parse after every insertion, else the
        entire heal is reverted.

    Conservative and honest: drops 0-arg pairs and any triple whose receiver
    is not a proven self-attr rather than guess."""
    import ast as _ast_mc
    if not text or not traces:
        return text
    try:
        tree = _ast_mc.parse(text)
    except Exception:
        return text
    self_attrs = set(re.findall(r'\bself\.([A-Za-z_]\w*)\b', text))
    if not self_attrs:
        return text
    # Methods already called on a NON-self receiver (module/global calls like
    # `time.sleep`). The faithful trace mis-binds such calls to the last
    # self-attr resolved, so we must NOT synthesize `self.X.<meth>` for them.
    nonself_methods = set()

    def _root_id(node):
        while isinstance(node, _ast_mc.Attribute):
            node = node.value
        return node.id if isinstance(node, _ast_mc.Name) else None

    for _n in _ast_mc.walk(tree):
        if isinstance(_n, _ast_mc.Call) and isinstance(_n.func, _ast_mc.Attribute):
            _rid = _root_id(_n.func)
            if _rid is not None and _rid != 'self':
                nonself_methods.add(_n.func.attr)
    # Self-attrs POSITIVELY assigned a non-Call value (str/int/name/...). A
    # triple whose receiver is in this set is skipped: calling .method() on a
    # proven non-object is fabricated nonsense (false trace triple-association
    # across statement boundaries). Does NOT reject lost-construction attrs
    # (referenced as self.X but never assigned in the emit) — those are real
    # objects whose construction the walker dropped and we still recover them.
    nonobject_attrs = set()
    for _n in _ast_mc.walk(tree):
        if (isinstance(_n, _ast_mc.Assign)
                and not isinstance(_n.value, _ast_mc.Call)):
            for _t in _n.targets:
                if (isinstance(_t, _ast_mc.Attribute)
                        and isinstance(_t.value, _ast_mc.Name)
                        and _t.value.id == 'self'):
                    nonobject_attrs.add(_t.attr)
    # Module-level / class method NAMES (def get_url, async def handle, ...).
    # A triple whose receiver is a def-name is skipped: a method name cannot
    # also be a self instance-attribute holding an object, so synthesizing
    # ``self.<methodname>.<x>(...)`` is fabricated nonsense (the trace
    # flattens a ``self.get_url()`` call + an unrelated trailing token into a
    # bogus ``self.get_url.mode()``). Safe for real widget receivers — a
    # widget instance attr is never a def name in the same class.
    def_names = set()
    for _n in _ast_mc.walk(tree):
        if isinstance(_n, (_ast_mc.FunctionDef, _ast_mc.AsyncFunctionDef)):
            def_names.add(_n.name)
    synth_by_qn = {}
    for _qn, _tstrs in (traces or {}).items():
        _stmts = _ndl_synth_method_calls_strict_v93(
            _tstrs, self_attrs, nonself_methods, nonobject_attrs, def_names)
        if _stmts:
            synth_by_qn[str(_qn)] = _stmts
    if not synth_by_qn:
        return text

    def _norm(s):
        s = str(s).strip()
        s = re.sub(r'\s*#.*$', '', s)
        return re.sub(r'\s+', ' ', s)

    lines = text.split("\n")
    edits = []   # each: ('replace'|'before'|'after', line_index_0based, indent, [stmts])
    cls_path = []

    def _qualname_depth_ok(qn):
        return qn in synth_by_qn

    def visit(node):
        if isinstance(node, _ast_mc.ClassDef):
            cls_path.append(node.name)
            for c in node.body:
                visit(c)
            cls_path.pop()
            return
        if isinstance(node, (_ast_mc.FunctionDef, _ast_mc.AsyncFunctionDef)):
            qn = ".".join(cls_path + [node.name]) if cls_path else node.name
            if qn in synth_by_qn and node.body:
                bstart = node.body[0].lineno - 1
                bend = (getattr(node.body[-1], 'end_lineno', None)
                        or node.body[-1].lineno) - 1
                existing = set()
                for i in range(bstart, bend + 1):
                    if 0 <= i < len(lines):
                        existing.add(_norm(lines[i]))
                missing = [s for s in synth_by_qn[qn]
                           if _norm(s) not in existing]
                if missing:
                    last = node.body[-1]
                    last_src = lines[last.lineno - 1]
                    indent = last_src[:len(last_src) - len(last_src.lstrip())]
                    if isinstance(last, _ast_mc.Pass):
                        edits.append(('replace', last.lineno - 1,
                                      indent, missing))
                    elif isinstance(last, (_ast_mc.Return, _ast_mc.Raise,
                                            _ast_mc.Break, _ast_mc.Continue)):
                        edits.append(('before', last.lineno - 1,
                                      indent, missing))
                    else:
                        end_ln = getattr(last, 'end_lineno', last.lineno)
                        edits.append(('after', end_ln, indent, missing))
            for c in node.body:
                visit(c)
            return
        body = getattr(node, 'body', None)
        if isinstance(body, list):
            for c in body:
                visit(c)
    for node in tree.body:
        visit(node)
    if not edits:
        return text
    # apply bottom-up so earlier line indices stay valid
    edits.sort(key=lambda e: e[1], reverse=True)
    new_lines = lines[:]
    for kind, idx, indent, stmts in edits:
        block = [indent + s for s in stmts]
        if kind == 'replace':
            new_lines[idx:idx + 1] = block
        else:
            new_lines[idx:idx] = block
    out = "\n".join(new_lines)
    try:
        _ast_mc.parse(out)
    except Exception:
        return text
    return out


def _ndl_heal_session_get_args_v36(text, consts=None):
    """V36: Reattach missing `url` argument to `self.session.get(...)` calls.

    When the per-statement walk recovers `self.session.get()` with no
    arguments (or only keyword arguments like `headers=...`), the original
    source almost always had a URL as the first positional argument.
    This healer:
      - Finds all URL-shaped string constants in `consts` (http://, https://).
      - For each `self.session.get(...)` call missing a positional url arg,
        reattaches the URL that appears most frequently in the function
        body (or the first URL const if none are referenced).
      - Conservative: only fires when the call has ZERO positional args
        (clearly missing), never overrides an existing positional.
    """
    if not text or not consts:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text

    # Collect URL constants from consts.
    _urls = []
    for c in consts:
        if (isinstance(c, str) and c.startswith(('http://', 'https://'))
                and len(c) < 200):
            _urls.append(c)
    if not _urls:
        return text

    # Collect URLs referenced anywhere in the text (to prefer ones already
    # partially recovered).
    _referenced = set()
    for url in _urls:
        if url in text:
            _referenced.add(url)

    class _S(_ast.NodeTransformer):
        def visit_Expr(self, node):
            self.generic_visit(node)
            if not isinstance(node.value, _ast.Call):
                return node
            return self._fix_call(node, node.value)

        def visit_Assign(self, node):
            self.generic_visit(node)
            if isinstance(node.value, _ast.Call):
                node.value = self._fix_call(node.value, node.value)
            return node

        def visit_Return(self, node):
            self.generic_visit(node)
            if isinstance(node.value, _ast.Call):
                node.value = self._fix_call(node.value, node.value)
            return node

        def _fix_call(self, parent, call):
            """If `call` is self.session.get() with no positional args,
            add a URL positional."""
            if not (isinstance(call.func, _ast.Attribute)
                    and isinstance(call.func.value, _ast.Attribute)
                    and isinstance(call.func.value.value, _ast.Name)
                    and call.func.value.value.id == 'self'
                    and call.func.value.attr == 'session'
                    and call.func.attr in ('get', 'post', 'put', 'delete', 'head', 'patch', 'request')):
                return parent
            if call.args:
                return parent  # already has a positional arg
            # Pick the URL to attach.
            url = None
            # Prefer a URL referenced in the same function body — find it
            # by walking the parent's ancestors is complex; just pick the
            # first referenced URL, or the first URL in consts.
            if _referenced:
                url = sorted(_referenced, key=lambda u: text.find(u))[0]
            else:
                url = _urls[0]
            call.args = [_ast.Constant(value=url)]
            _ast.fix_missing_locations(parent)
            return parent

    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text

def _ndl_heal_dropEvent_super_v35(text):
    """V35: Add `super().dropEvent(event)` to overridden Qt event handlers.

    When a class subclasses a Qt widget and overrides an event handler
    (dropEvent, mousePressEvent, keyPressEvent, ...), the source almost
    always calls `super().<event>(event)` to propagate the event. The
    native recovery frequently drops this call (it's an out-of-line
    tail call after the user code), producing a body that has only
    `self.order_changed.emit()` and silently swallows the event.

    This healer inspects each class body for `def <event>(self, event):`
    methods (where <event> is a known Qt event handler name) and inserts
    `super().<event>(event)` as the LAST statement when no super call is
    present.

    Also replaces the two-helper-validator synth garbage
    (``expected = dropEvent(self); if not expected or not ...``) with the
    evidence-backed ``super().dropEvent(event)`` + ``self.<signal>.emit()``
    shape when the class declares a Signal attribute.
    """
    if not text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    _QT_EVENTS = {
        'dropEvent', 'mousePressEvent', 'mouseReleaseEvent',
        'mouseMoveEvent', 'mouseDoubleClickEvent',
        'keyPressEvent', 'keyReleaseEvent',
        'wheelEvent', 'focusInEvent', 'focusOutEvent',
        'resizeEvent', 'paintEvent', 'closeEvent',
        'dragEnterEvent', 'dragMoveEvent', 'dragLeaveEvent',
        'contextMenuEvent', 'showEvent', 'hideEvent',
        'enterEvent', 'leaveEvent', 'tabletEvent', 'hoverMoveEvent',
    }

    def _has_super_call(node, method_name):
        for sub in _ast.walk(node):
            if (isinstance(sub, _ast.Expr) and isinstance(sub.value, _ast.Call)
                    and isinstance(sub.value.func, _ast.Attribute)
                    and isinstance(sub.value.func.value, _ast.Call)
                    and isinstance(sub.value.func.value.func, _ast.Name)
                    and sub.value.func.value.func.id == 'super'
                    and sub.value.func.attr == method_name):
                return True
        return False

    def _is_validator_garbage(fn):
        """True for the fake two-helper synth pattern."""
        try:
            txt = _ast.unparse(fn)
        except Exception:
            return False
        if 'expected =' not in txt:
            return False
        if 'if not expected or not' not in txt:
            return False
        return 'return False' in txt or 'return ' in txt

    def _signal_names(cls):
        names = set()
        for s in cls.body:
            if isinstance(s, _ast.Assign):
                try:
                    rhs = _ast.unparse(s.value)
                except Exception:
                    rhs = ''
                if 'Signal(' in rhs or 'pyqtSignal(' in rhs:
                    for t in s.targets:
                        if isinstance(t, _ast.Name):
                            names.add(t.id)
        return names

    class _S(_ast.NodeTransformer):
        def visit_ClassDef(self, node):
            self.generic_visit(node)
            if not node.bases:
                return node
            signals = _signal_names(node)
            for item in node.body:
                if (isinstance(item, _ast.FunctionDef)
                        and item.name in _QT_EVENTS
                        and len(item.args.args) >= 2):
                    arg_name = item.args.args[1].arg
                    if _is_validator_garbage(item):
                        # Replace fabricated validator with super + signal emit.
                        new_body = [
                            _ast.parse('super().%s(%s)' % (
                                item.name, arg_name)).body[0]
                        ]
                        if signals and item.name == 'dropEvent':
                            # Prefer order_changed-style names when present.
                            sig = next(
                                (s for s in sorted(signals)
                                 if 'order' in s or 'change' in s
                                 or 'drop' in s or 'reorder' in s),
                                sorted(signals)[0])
                            new_body.append(
                                _ast.parse(
                                    'self.%s.emit()' % sig).body[0])
                        item.body = new_body
                        continue
                    # Drop bare ``dropEvent()`` leftovers from failed recovery.
                    item.body = [
                        s for s in item.body
                        if not (
                            isinstance(s, _ast.Expr)
                            and isinstance(s.value, _ast.Call)
                            and isinstance(s.value.func, _ast.Name)
                            and s.value.func.id == item.name
                        )
                    ] or [_ast.Pass()]
                    if not _has_super_call(item, item.name):
                        sc = _ast.parse('super().%s(%s)' % (
                            item.name, arg_name)).body[0]
                        item.body.append(sc)
                    # Enforce super before signal.emit for dropEvent.
                    if item.name == 'dropEvent' and signals:
                        def _is_emit(s):
                            if not (isinstance(s, _ast.Expr)
                                    and isinstance(s.value, _ast.Call)):
                                return False
                            f = s.value.func
                            return (isinstance(f, _ast.Attribute)
                                    and f.attr == 'emit'
                                    and isinstance(f.value, _ast.Attribute)
                                    and isinstance(f.value.value, _ast.Name)
                                    and f.value.value.id == 'self'
                                    and f.value.attr in signals)
                        def _is_super(s):
                            try:
                                return 'super().dropEvent' in _ast.unparse(s)
                            except Exception:
                                return False
                        body = item.body
                        si = next((i for i, s in enumerate(body) if _is_super(s)), None)
                        ei = next((i for i, s in enumerate(body) if _is_emit(s)), None)
                        if si is not None and ei is not None and ei < si:
                            em = body.pop(ei)
                            si = next((i for i, s in enumerate(body) if _is_super(s)), len(body) - 1)
                            body.insert(si + 1, em)
                        elif si is not None and ei is None:
                            sig = next(
                                (s for s in sorted(signals)
                                 if 'order' in s or 'change' in s
                                 or 'drop' in s or 'reorder' in s),
                                sorted(signals)[0])
                            body.insert(si + 1, _ast.parse(
                                'self.%s.emit()' % sig).body[0])
            return node
    tree = _S().visit(tree)
    _ast.fix_missing_locations(tree)
    try:
        _r = _ast.unparse(tree)
        try:
            _r = _ndl_ensure_block_bodies(_r)
        except Exception:
            pass
        return _r
    except Exception:
        return text


def _ndl_heal_spurious_local_call_tests_v51(text):
    """``if foo():`` / ``if not foo():`` → ``if foo:`` when *foo* is a local.

    Walkers sometimes wrap a truth-test of a local (assigned from
    ``currentItem()`` / ``text().strip()``) as a zero-arg call on the name.
    A Name that was stored earlier in the same function is an object, not a
    callable — calling it is almost always wrong.
    """
    if not text or '():' not in text:
        return text
    import ast as _ast
    try:
        tree = _ast.parse(text)
    except Exception:
        return text
    changed = False

    class _S(_ast.NodeTransformer):
        def visit_FunctionDef(self, node):
            nonlocal changed
            assigned = set()
