                if (not has_sl and layout_nm not in used
                        and not any(k in low for k in (
                            'button', 'btn', 'action', 'tool'))):
                    out.append(_ast.parse(
                        '%s.setLayout(%s)' % (cur_group, layout_nm)
                    ).body[0])
                    used.add(layout_nm)
                    changed = True

