        if cat == "METHOD":
            _raw_rdx = store.get("rdx")
            src = self._clean(_raw_rdx, last)
            if (src is None or (isinstance(src.t, str) and src.t == "_v")
                    or self._is_bare_class_path(src)):
                src = None
                for alt in (last, store.get("rax"), store.get("_item")):
                    if (self._is_clean(alt) and alt.t != "_v"
                            and not self._is_bare_class_path(alt)):
                        src = alt
                        break
