        if cat == "SETATTR":
            # SET_ATTRIBUTE(tstate, target, attr_name_const, value):
            #   rdx = target object   r8 = attribute-name const   r9 = value
            # -> the STATEMENT `target.attr = value` (not a value expression).
            tgt = self._clean(store.get("rdx"), last)
            if tgt is None or (isinstance(tgt.t, str) and tgt.t == "_v"):
                for alt in (last, store.get("rax")):
                    if self._is_clean(alt) and alt.t != "_v":
                        tgt = alt
                        break
